import { canonicalizeJson } from "../../domain/canonical-json.js";
import { canonicalSha256 } from "../../domain/hashing.js";
import type { Sha256Digest } from "../../domain/types.js";
import {
  canonicalRawSignatureV1,
  computePermitDigestV1,
  computeSafeMessageSigningDigestV1,
  safeMessageTypedDataV1,
  type LaunchPermitV1,
} from "./abi-codec.js";
import {
  PRODUCTION_ROUTER_SELF_SERVICE_BINDING_V1 as BINDING,
  type EvmAddressV1,
  type EvmBytes32V1,
  type EvmHexV1,
} from "./production-binding.js";

/**
 * Browser request shown only to the current human Safe owner. There is no
 * autonomous signer, KMS adapter, remote executor, or contract-owner path in
 * this beta.
 */
export interface AdminMetaMaskSafeMessageRequestV1 {
  readonly schemaVersion: "programmable.admin-metamask-safe-message-request.v1";
  readonly method: "eth_signTypedData_v4";
  readonly chainId: "0x1";
  readonly requiredAccount: EvmAddressV1;
  readonly safe: EvmAddressV1;
  readonly permitDigest: EvmBytes32V1;
  readonly safeMessageDigest: EvmBytes32V1;
  readonly typedData: ReturnType<typeof safeMessageTypedDataV1>;
  readonly params: readonly [EvmAddressV1, string];
  readonly issuedAtChainTimestamp: string;
  readonly expiresAtChainTimestamp: string;
  readonly signingRequestHash: Sha256Digest;
}

export interface ManualSafeOwnerSignatureV1 {
  readonly schemaVersion: "programmable.manual-safe-owner-signature.v1";
  readonly signingRequestHash: Sha256Digest;
  readonly rawSignature65: EvmHexV1;
  readonly signatureHash: Sha256Digest;
}

export function createAdminMetaMaskSafeMessageRequestV1(input: Readonly<{
  permit: Readonly<LaunchPermitV1>;
  permitDigest: EvmBytes32V1;
  issuedAtChainTimestamp: string;
}>): Readonly<AdminMetaMaskSafeMessageRequestV1> {
  const issuedAt = uintString(input.issuedAtChainTimestamp, "signing-request chain timestamp");
  const permitDigest = bytes32(input.permitDigest, "permit digest");
  if (computePermitDigestV1(input.permit) !== permitDigest) {
    throw new TypeError("manual signing request permit digest is inconsistent");
  }
  if (
    input.permit.router !== BINDING.router.address
    || input.permit.chainId !== BINDING.chain.chainIdDecimal
    || BigInt(input.permit.deadline) - BigInt(input.permit.validAfter)
      > BigInt(BINDING.permit.manualMaximumLifetimeSeconds)
    || BigInt(issuedAt) < BigInt(input.permit.validAfter)
    || BigInt(issuedAt) > BigInt(input.permit.deadline)
  ) throw new TypeError("manual signing request permit binding or lifetime is invalid");
  const typedData = safeMessageTypedDataV1(permitDigest);
  const safeMessageDigest = computeSafeMessageSigningDigestV1(permitDigest);
  const core = {
    schemaVersion: "programmable.admin-metamask-safe-message-request.v1" as const,
    method: "eth_signTypedData_v4" as const,
    chainId: BINDING.chain.chainIdHex,
    requiredAccount: BINDING.permitAuthoritySafe.manualOwner,
    safe: BINDING.permitAuthoritySafe.address,
    permitDigest,
    safeMessageDigest,
    typedData,
    params: [
      BINDING.permitAuthoritySafe.manualOwner,
      JSON.stringify(typedData),
    ] as const,
    issuedAtChainTimestamp: issuedAt,
    expiresAtChainTimestamp: input.permit.deadline,
  };
  return deepFreeze({
    ...core,
    signingRequestHash: canonicalSha256(
      "programmable.admin-metamask-safe-message-request.v1",
      core,
    ),
  });
}

export function assertAdminMetaMaskSafeMessageRequestV1(
  raw: AdminMetaMaskSafeMessageRequestV1,
): Readonly<AdminMetaMaskSafeMessageRequestV1> {
  assertExactKeys(raw, [
    "chainId", "expiresAtChainTimestamp", "issuedAtChainTimestamp", "method", "params",
    "permitDigest", "requiredAccount", "safe", "safeMessageDigest", "schemaVersion",
    "signingRequestHash", "typedData",
  ], "admin MetaMask SafeMessage request");
  if (
    raw.schemaVersion !== "programmable.admin-metamask-safe-message-request.v1"
    || raw.method !== "eth_signTypedData_v4"
    || raw.chainId !== BINDING.chain.chainIdHex
    || raw.requiredAccount !== BINDING.permitAuthoritySafe.manualOwner
    || raw.safe !== BINDING.permitAuthoritySafe.address
  ) throw new TypeError("admin MetaMask SafeMessage request production binding is invalid");
  const permitDigest = bytes32(raw.permitDigest, "admin request permit digest");
  const typedData = safeMessageTypedDataV1(permitDigest);
  const issuedAt = uintString(raw.issuedAtChainTimestamp, "admin request issued-at");
  const expiresAt = uintString(raw.expiresAtChainTimestamp, "admin request expiry");
  if (
    raw.safeMessageDigest !== computeSafeMessageSigningDigestV1(permitDigest)
    || canonicalizeJson(raw.typedData) !== canonicalizeJson(typedData)
    || raw.params.length !== 2
    || raw.params[0] !== BINDING.permitAuthoritySafe.manualOwner
    || raw.params[1] !== JSON.stringify(typedData)
    || BigInt(issuedAt) > BigInt(expiresAt)
  ) throw new TypeError("admin MetaMask SafeMessage request preimage is invalid");
  const { signingRequestHash: _, ...core } = raw;
  if (raw.signingRequestHash !== canonicalSha256(
    "programmable.admin-metamask-safe-message-request.v1",
    core,
  )) throw new TypeError("admin MetaMask SafeMessage request hash is invalid");
  return deepFreeze({ ...raw });
}

export function acceptManualSafeOwnerSignatureV1(input: Readonly<{
  request: AdminMetaMaskSafeMessageRequestV1;
  rawSignature65: EvmHexV1;
}>): Readonly<ManualSafeOwnerSignatureV1> {
  const request = assertAdminMetaMaskSafeMessageRequestV1(input.request);
  const rawSignature65 = canonicalRawSignatureV1(input.rawSignature65);
  const core = {
    schemaVersion: "programmable.manual-safe-owner-signature.v1" as const,
    signingRequestHash: request.signingRequestHash,
    rawSignature65,
  };
  return deepFreeze({
    ...core,
    signatureHash: canonicalSha256("programmable.manual-safe-owner-signature.v1", core),
  });
}

function assertExactKeys(
  value: unknown,
  expected: readonly string[],
  label: string,
): asserts value is Record<string, unknown> {
  if (value === null || typeof value !== "object" || Array.isArray(value)) {
    throw new TypeError(`${label} is not an object`);
  }
  const actual = Object.keys(value).sort();
  const required = [...expected].sort();
  if (actual.length !== required.length || actual.some((key, index) => key !== required[index])) {
    throw new TypeError(`${label} has unexpected fields`);
  }
}

function uintString(value: unknown, label: string): string {
  if (typeof value !== "string" || !/^(?:0|[1-9][0-9]*)$/u.test(value)) {
    throw new TypeError(`${label} is invalid`);
  }
  return value;
}

function bytes32(value: unknown, label: string): EvmBytes32V1 {
  if (typeof value !== "string" || !/^0x[0-9a-f]{64}$/u.test(value)) {
    throw new TypeError(`${label} is invalid`);
  }
  return value as EvmBytes32V1;
}

function deepFreeze<T>(value: T): T {
  if (value !== null && typeof value === "object" && !Object.isFrozen(value)) {
    for (const nested of Object.values(value as Record<string, unknown>)) deepFreeze(nested);
    Object.freeze(value);
  }
  return value;
}
