import {
  canonicalizeJson,
} from "../../domain/canonical-json.js";
import { canonicalSha256 } from "../../domain/hashing.js";
import type { Sha256Digest } from "../../domain/types.js";
import { framedKeccakV1 } from "./keccak.js";
import {
  PRODUCTION_ROUTER_SELF_SERVICE_BINDING_V1 as BINDING,
  type EvmAddressV1,
  type EvmBytes32V1,
} from "./production-binding.js";

export interface RouterRouteNonceSeedV1 {
  readonly schemaVersion: "programmable.router-route-nonce-seed.v3";
  readonly repositoryId: string;
  readonly pullRequestNumber: number;
  readonly headRepositoryId: string;
  readonly headSha: string;
  readonly treeSha: string;
  readonly approvedGitHubUserId: string;
  readonly approvalRevisionHash: Sha256Digest;
  /** Hash of every normalized source, bytecode, target, pool, and toolchain input. */
  readonly compileInputHash: Sha256Digest;
  readonly launchWallet: EvmAddressV1;
}

export interface RouterCustomGraphCompileRequestV1 {
  readonly schemaVersion: "programmable.router-custom-graph-compile-request.v3";
  readonly chainId: "1";
  readonly router: EvmAddressV1;
  readonly graphFactory: EvmAddressV1;
  /** The Router, never the applicant wallet, calls the GraphFactory. */
  readonly authorizedLauncher: EvmAddressV1;
  readonly repositoryId: string;
  readonly pullRequestNumber: number;
  readonly headRepositoryId: string;
  readonly headSha: string;
  readonly treeSha: string;
  readonly approvedGitHubUserId: string;
  readonly approvalRevisionHash: Sha256Digest;
  readonly compileInputHash: Sha256Digest;
  readonly launchWallet: EvmAddressV1;
  readonly preflightAuthorityBindingHash: Sha256Digest;
  readonly graphRouteAdapterRegistryHash: Sha256Digest;
  readonly routeNamespace: EvmBytes32V1;
  readonly routeGenerationHash: Sha256Digest;
  readonly routeNonce: EvmBytes32V1;
  readonly compileRequestHash: Sha256Digest;
}

export function canonicalRouterRouteNonceSeedV1(
  raw: RouterRouteNonceSeedV1,
): Readonly<RouterRouteNonceSeedV1> {
  assertExactKeys(raw, [
    "approvalRevisionHash", "approvedGitHubUserId", "compileInputHash", "headRepositoryId",
    "headSha", "launchWallet", "pullRequestNumber", "repositoryId", "schemaVersion", "treeSha",
  ], "Router route-nonce seed");
  if (raw.schemaVersion !== "programmable.router-route-nonce-seed.v3") {
    throw new TypeError("Router route-nonce seed schema is invalid");
  }
  return deepFreeze({
    schemaVersion: raw.schemaVersion,
    repositoryId: numericId(raw.repositoryId, "repository id"),
    pullRequestNumber: positiveSafeInteger(raw.pullRequestNumber, "pull-request number"),
    headRepositoryId: numericId(raw.headRepositoryId, "head repository id"),
    headSha: gitSha(raw.headSha, "head SHA"),
    treeSha: gitSha(raw.treeSha, "tree SHA"),
    approvedGitHubUserId: numericId(raw.approvedGitHubUserId, "approved GitHub user id"),
    approvalRevisionHash: sha256(raw.approvalRevisionHash, "approval revision hash"),
    compileInputHash: sha256(raw.compileInputHash, "compiler input hash"),
    launchWallet: address(raw.launchWallet, "launch wallet"),
  });
}

export function deriveRouterRouteGenerationHashV1(
  raw: RouterRouteNonceSeedV1,
): Sha256Digest {
  const seed = canonicalRouterRouteNonceSeedV1(raw);
  return canonicalSha256("programmable.router-route-generation.v1", {
    chainId: BINDING.chain.chainIdDecimal,
    router: BINDING.router.address,
    graphFactory: BINDING.graphFactory.address,
    ...seed,
  });
}

/**
 * Uses the canonical Graph compiler nonce derivation. The namespace and route
 * generation hash exist before any CREATE2 address, graph commitment, plan, or
 * permit is materialized, so no hash cycle or post-compile rewrite exists.
 */
export function deriveDeterministicRouteNonceV1(input: Readonly<{
  seed: RouterRouteNonceSeedV1;
  routeNamespace: EvmBytes32V1;
}>): EvmBytes32V1 {
  const routeNamespace = bytes32(input.routeNamespace, "route namespace");
  const routeGenerationHash = deriveRouterRouteGenerationHashV1(input.seed);
  const nonce = framedKeccakV1("programmable.create2-graph-route-nonce.v1", [
    Uint8Array.from(Buffer.from(routeNamespace.slice(2), "hex")),
    Uint8Array.from(Buffer.from(routeGenerationHash.slice("sha256:".length), "hex")),
  ]) as EvmBytes32V1;
  if (BigInt(nonce) === 0n) throw new TypeError("derived Router route nonce is zero");
  return nonce;
}

export function createCustomGraphCompileRequestV1(input: Readonly<{
  seed: RouterRouteNonceSeedV1;
  routeNamespace: EvmBytes32V1;
  preflightAuthorityBindingHash: Sha256Digest;
  graphRouteAdapterRegistryHash: Sha256Digest;
}>): Readonly<RouterCustomGraphCompileRequestV1> {
  const seed = canonicalRouterRouteNonceSeedV1(input.seed);
  const routeNamespace = bytes32(input.routeNamespace, "route namespace");
  const preflightAuthorityBindingHash = sha256(
    input.preflightAuthorityBindingHash,
    "preflight authority binding hash",
  );
  const graphRouteAdapterRegistryHash = sha256(
    input.graphRouteAdapterRegistryHash,
    "graph route adapter registry hash",
  );
  const routeGenerationHash = deriveRouterRouteGenerationHashV1(seed);
  const core = {
    schemaVersion: "programmable.router-custom-graph-compile-request.v3" as const,
    chainId: "1" as const,
    router: BINDING.router.address,
    graphFactory: BINDING.graphFactory.address,
    authorizedLauncher: BINDING.router.address,
    repositoryId: seed.repositoryId,
    pullRequestNumber: seed.pullRequestNumber,
    headRepositoryId: seed.headRepositoryId,
    headSha: seed.headSha,
    treeSha: seed.treeSha,
    approvedGitHubUserId: seed.approvedGitHubUserId,
    approvalRevisionHash: seed.approvalRevisionHash,
    compileInputHash: seed.compileInputHash,
    launchWallet: seed.launchWallet,
    preflightAuthorityBindingHash,
    graphRouteAdapterRegistryHash,
    routeNamespace,
    routeGenerationHash,
    routeNonce: deriveDeterministicRouteNonceV1({ seed, routeNamespace }),
  };
  return deepFreeze({
    ...core,
    compileRequestHash: canonicalSha256(
      "programmable.router-custom-graph-compile-request.v3",
      core,
    ),
  });
}

export function assertCustomGraphCompileRequestV1(
  raw: RouterCustomGraphCompileRequestV1,
): Readonly<RouterCustomGraphCompileRequestV1> {
  assertExactKeys(raw, [
    "approvalRevisionHash", "approvedGitHubUserId", "authorizedLauncher", "chainId", "compileInputHash",
    "compileRequestHash", "graphFactory", "graphRouteAdapterRegistryHash", "headRepositoryId",
    "headSha", "launchWallet", "preflightAuthorityBindingHash", "pullRequestNumber", "repositoryId",
    "routeGenerationHash", "routeNamespace", "routeNonce", "router", "schemaVersion", "treeSha",
  ], "Router CustomGraph compile request");
  if (
    raw.schemaVersion !== "programmable.router-custom-graph-compile-request.v3"
    || raw.chainId !== BINDING.chain.chainIdDecimal
    || raw.router !== BINDING.router.address
    || raw.graphFactory !== BINDING.graphFactory.address
    || raw.authorizedLauncher !== BINDING.router.address
  ) throw new TypeError("Router CustomGraph compile request production binding is invalid");
  const rebuilt = createCustomGraphCompileRequestV1({
    seed: {
      schemaVersion: "programmable.router-route-nonce-seed.v3",
      repositoryId: raw.repositoryId,
      pullRequestNumber: raw.pullRequestNumber,
      headRepositoryId: raw.headRepositoryId,
      headSha: raw.headSha,
      treeSha: raw.treeSha,
      approvedGitHubUserId: raw.approvedGitHubUserId,
      approvalRevisionHash: raw.approvalRevisionHash,
      compileInputHash: raw.compileInputHash,
      launchWallet: raw.launchWallet,
    },
    routeNamespace: raw.routeNamespace,
    preflightAuthorityBindingHash: raw.preflightAuthorityBindingHash,
    graphRouteAdapterRegistryHash: raw.graphRouteAdapterRegistryHash,
  });
  if (canonicalizeJson(raw) !== canonicalizeJson(rebuilt)) {
    throw new TypeError("Router CustomGraph compile request provenance is invalid");
  }
  return rebuilt;
}

function positiveSafeInteger(value: unknown, label: string): number {
  if (!Number.isSafeInteger(value) || (value as number) <= 0) {
    throw new TypeError(`${label} is invalid`);
  }
  return value as number;
}

function assertExactKeys(
  value: unknown,
  expected: readonly string[],
  label: string,
): asserts value is Record<string, unknown> {
  if (value === null || typeof value !== "object" || Array.isArray(value)) {
    throw new TypeError(`${label} is not an object`);
  }
  const actual = Object.keys(value).sort();
  const required = [...expected].sort();
  if (actual.length !== required.length || actual.some((key, index) => key !== required[index])) {
    throw new TypeError(`${label} has unexpected fields`);
  }
}

function numericId(value: unknown, label: string): string {
  if (typeof value !== "string" || !/^[1-9][0-9]{0,19}$/u.test(value)) {
    throw new TypeError(`${label} is invalid`);
  }
  return value;
}

function gitSha(value: unknown, label: string): string {
  if (typeof value !== "string" || !/^[0-9a-f]{40}$/u.test(value)) {
    throw new TypeError(`${label} is invalid`);
  }
  return value;
}

function sha256(value: unknown, label: string): Sha256Digest {
  if (typeof value !== "string" || !/^sha256:[0-9a-f]{64}$/u.test(value)) {
    throw new TypeError(`${label} is invalid`);
  }
  return value as Sha256Digest;
}

function bytes32(value: unknown, label: string): EvmBytes32V1 {
  if (typeof value !== "string" || !/^0x[0-9a-fA-F]{64}$/u.test(value)) {
    throw new TypeError(`${label} is invalid`);
  }
  const normalized = value.toLowerCase() as EvmBytes32V1;
  if (BigInt(normalized) === 0n) throw new TypeError(`${label} is zero`);
  return normalized;
}

function address(value: unknown, label: string): EvmAddressV1 {
  if (typeof value !== "string" || !/^0x[0-9a-fA-F]{40}$/u.test(value)) {
    throw new TypeError(`${label} is invalid`);
  }
  const normalized = value.toLowerCase() as EvmAddressV1;
  if (BigInt(normalized) === 0n) throw new TypeError(`${label} is zero`);
  return normalized;
}

function deepFreeze<T>(value: T): T {
  if (value !== null && typeof value === "object" && !Object.isFrozen(value)) {
    for (const nested of Object.values(value as Record<string, unknown>)) deepFreeze(nested);
    Object.freeze(value);
  }
  return value;
}
