import type { CheckRunPayload } from "../github/check-run.js";
import type { GitObjectFormat } from "../github/contracts.js";
import type { GitObjectReader } from "../github/ports.js";

export type { GitObjectFormat } from "../github/contracts.js";

export const GITHUB_REST_API_VERSION = "2026-03-10" as const;
export const GITHUB_REST_ACCEPT = "application/vnd.github+json" as const;
export const GITHUB_REST_USER_AGENT = "programmable-autonomous-approval-v1" as const;

export interface InstallationAccessToken {
  readonly token: string;
  readonly issuedAtEpochSeconds: number;
  readonly expiresAtEpochSeconds: number;
}

export interface InstallationTokenProvider {
  getInstallationToken(input: Readonly<{
    installationId: string;
    repositoryId: string;
  }>): Promise<InstallationAccessToken>;
}

export interface GitHubRestLogEvent {
  readonly operation: GitHubRestOperation;
  readonly method: "GET" | "POST" | "PATCH";
  readonly repositoryId: string;
  readonly attempt: number;
  readonly status?: number;
  readonly errorCode?: string;
}

export type GitHubRestLogger = (event: GitHubRestLogEvent) => void;

export type GitHubRestOperation =
  | "repository.get"
  | "user.get-by-id"
  | "collaborator-permission.get"
  | "commit.get"
  | "tree.get"
  | "blob.get"
  | "source.get-at-commit"
  | "pull-request.get"
  | "pull-request.review.get"
  | "pull-request.files.list"
  | "check-run.get"
  | "check-runs.list"
  | "check-run.create"
  | "check-run.update";

export interface GitHubRestLimits {
  readonly requestTimeoutMs: number;
  readonly maximumReadAttempts: number;
  readonly retryBaseDelayMs: number;
  readonly maximumMetadataResponseBytes: number;
  readonly maximumCommitResponseBytes: number;
  readonly maximumTreeResponseBytes: number;
  readonly maximumPullRequestFilesPageResponseBytes: number;
  readonly maximumCheckResponseBytes: number;
  readonly maximumTreeEntries: number;
  readonly maximumPathBytes: number;
  readonly maximumPathDepth: number;
  readonly maximumAggregatePathBytes: number;
  readonly maximumSourceFileBytes: number;
  readonly maximumDeclaredTreeBytes: number;
  readonly maximumCommitParents: number;
  readonly maximumPullRequestFiles: number;
  readonly maximumWriteBodyBytes: number;
}

export interface GitHubRestAdapterOptions {
  readonly fetch: typeof fetch;
  /** Stable numeric id of the only GitHub App permitted to own emitted checks. */
  readonly appId: string;
  readonly installationId: string;
  readonly tokenProvider: InstallationTokenProvider;
  readonly limits?: Partial<GitHubRestLimits>;
  readonly nowEpochSeconds?: () => number;
  readonly sleep?: (milliseconds: number) => Promise<void>;
  readonly logger?: GitHubRestLogger;
}

export interface ExactRepositoryMetadata {
  readonly repositoryId: string;
  readonly nodeId: string;
  readonly ownerId: string;
  readonly ownerLogin: string;
  readonly name: string;
  readonly fullName: string;
  readonly visibility: "public" | "private";
  readonly archived: boolean;
  readonly disabled: boolean;
  readonly defaultBranch: string | null;
  /** Null only when GitHub omitted the repository object-format field. */
  readonly objectFormat: GitObjectFormat | null;
  /** Provider provenance used by deployment-rights review; undefined means not observed. */
  readonly fork?: boolean;
  readonly parentRepositoryId?: string | null;
  readonly sourceRepositoryId?: string | null;
  readonly licenseSpdxId?: string | null;
}

export interface ExactRepositoryPermissionObservation {
  readonly repository: ExactRepositoryMetadata;
  /** Durable GitHub account identity resolved from the numeric id first. */
  readonly userId: string;
  readonly userNodeId: string;
  readonly userLogin: string;
  /** GitHub's legacy base permission. Custom admin roles map to `admin`. */
  readonly permission: "admin" | "write" | "read" | "none";
  readonly roleName: string | null;
}

export interface ExactGitCommit {
  readonly repository: ExactRepositoryMetadata;
  /** Port-compatible alias consumed by the inert snapshot resolver. */
  readonly sha: string;
  readonly commitSha: string;
  readonly treeSha: string;
  readonly parentShas: readonly string[];
  readonly objectFormat: GitObjectFormat;
}

export type ExactGitTreeEntryType = "blob" | "tree" | "commit";

export interface ExactGitTreeEntry {
  readonly path: string;
  readonly mode: string;
  readonly type: ExactGitTreeEntryType;
  readonly objectSha: string;
  /** Port-compatible alias consumed by the inert snapshot resolver. */
  readonly sha: string;
  readonly size: number | null;
}

export interface ExactGitTree {
  readonly repository: ExactRepositoryMetadata;
  /** Port-compatible alias consumed by the inert snapshot resolver. */
  readonly sha: string;
  readonly treeSha: string;
  readonly truncated: false;
  readonly entries: readonly ExactGitTreeEntry[];
  readonly declaredBlobBytes: number;
  readonly objectFormat: GitObjectFormat;
}

export interface ExactGitBlob {
  readonly repository: ExactRepositoryMetadata;
  readonly sha: string;
  readonly size: number;
  readonly bytes: Uint8Array;
  readonly objectFormat: GitObjectFormat;
}

export interface ExactSourceFile {
  readonly repository: ExactRepositoryMetadata;
  readonly commitSha: string;
  readonly path: string;
  readonly blobSha: string;
  readonly bytes: Uint8Array;
  readonly objectFormat: GitObjectFormat;
}

export interface ExactPullRequestHeadBinding {
  readonly baseRepositoryId: string;
  readonly headRepositoryId: string;
  readonly pullRequestNumber: number;
  readonly headSha: string;
  readonly baseSha: string;
  readonly objectFormat?: GitObjectFormat;
}

export interface ExactRevalidatedPullRequestHead {
  readonly schemaVersion: "1.0.0";
  readonly kind: "pull-request-head";
  readonly baseRepositoryId: string;
  readonly headRepositoryId: string;
  readonly pullRequestNumber: number;
  readonly headSha: string;
  readonly baseSha: string;
  readonly objectFormat: GitObjectFormat;
}

/** Exact immutable fields from one formal GitHub pull-request review. */
export interface ExactPullRequestReview {
  readonly baseRepositoryId: string;
  readonly pullRequestNumber: number;
  readonly reviewId: string;
  readonly reviewerUserId: string;
  readonly state: "APPROVED";
  readonly reviewedCommitSha: string;
  readonly submittedAt: string;
  readonly bodySha256: `sha256:${string}`;
}

/**
 * The only pull-request file fields admitted into intake classification. Diff
 * patches, URLs, repository names, and mutable refs are deliberately dropped.
 */
export interface ExactPullRequestFileChange {
  readonly filename: string;
  readonly status: "added" | "modified" | "removed" | "renamed" | "copied" | "changed" | "unchanged";
  readonly additions: number;
  readonly deletions: number;
  readonly changes: number;
  readonly previous_filename?: string;
}

export interface PublishedCheckRun {
  readonly repository: ExactRepositoryMetadata;
  readonly checkRunId: string;
  readonly headSha: string;
  readonly name: string;
  readonly externalId: string;
  /** Identity observed in GitHub's response, not copied from the request. */
  readonly app: {
    readonly appId: string;
    readonly nodeId: string;
    readonly slug: string;
  };
  /** Immutable credential scope of the reviewed adapter that made the request. */
  readonly installationId: string;
  readonly transportBindingHash: `sha256:${string}`;
  readonly status: "queued" | "in_progress" | "completed";
  readonly conclusion: string | null;
}

export interface GitHubRestAdapter extends GitObjectReader {
  getRepositoryMetadata(input: Readonly<{ repositoryId: string }>): Promise<ExactRepositoryMetadata>;

  /**
   * Resolves a mutable login from the durable numeric user id, then asks
   * GitHub for that exact user's effective repository permission. A response
   * user substitution is rejected.
   */
  observeRepositoryPermissionForUser(input: Readonly<{
    repositoryId: string;
    userId: string;
  }>): Promise<ExactRepositoryPermissionObservation>;

  readCommit(input: Readonly<{
    repositoryId: string;
    commitSha: string;
  }>): Promise<ExactGitCommit>;

  readTree(input: Readonly<{
    repositoryId: string;
    treeSha: string;
    recursive?: false;
  }>): Promise<ExactGitTree>;

  readBlob(input: Readonly<{
    repositoryId: string;
    blobSha: string;
  }>): Promise<ExactGitBlob>;

  readSourcePath(input: Readonly<{
    repositoryId: string;
    commitSha: string;
    path: string;
  }>): Promise<ExactSourceFile>;

  revalidatePullRequest(input: Readonly<{
    binding: ExactPullRequestHeadBinding;
    /** Defaults to false so approval/publication paths remain ready-only. */
    expectedDraft?: boolean;
  }>): Promise<ExactRevalidatedPullRequestHead>;

  /** Reads one formal review by provider id; no list/latest selection exists. */
  readPullRequestReview(input: Readonly<{
    repositoryId: string;
    pullRequestNumber: number;
    reviewId: string;
  }>): Promise<ExactPullRequestReview>;

  /**
   * Reads every page and proves the aggregate count equals the GitHub-authored
   * `changed_files` value from the exact signed pull-request event.
   */
  listPullRequestFiles(input: Readonly<{
    repositoryId: string;
    pullRequestNumber: number;
    expectedChangedFiles: number;
  }>): Promise<readonly ExactPullRequestFileChange[]>;

  /**
   * Reads the bounded, provider-authored set owned by this exact GitHub App on
   * one immutable commit. A caller uses the cardinality to reconcile an
   * ambiguous create without issuing a second write.
   */
  findCheckRunsForRef(input: Readonly<{
    repositoryId: string;
    expectedHeadSha: string;
    expectedName: string;
    expectedExternalId: string;
  }>): Promise<readonly PublishedCheckRun[]>;

  /** Re-reads one exact provider object before or after an ambiguous update. */
  getCheckRun(input: Readonly<{
    repositoryId: string;
    checkRunId: string;
    expectedHeadSha: string;
    expectedName: string;
    expectedExternalId: string;
  }>): Promise<PublishedCheckRun>;

  createCheckRun(input: Readonly<{
    repositoryId: string;
    expectedHeadSha: string;
    payload: CheckRunPayload;
  }>): Promise<PublishedCheckRun>;

  updateCheckRun(input: Readonly<{
    repositoryId: string;
    checkRunId: string;
    expectedHeadSha: string;
    payload: CheckRunPayload;
  }>): Promise<PublishedCheckRun>;
}
