import { canonicalizeJson } from "../../domain/canonical-json.js";
import { canonicalSha256 } from "../../domain/hashing.js";
import type { Sha256Digest } from "../../domain/types.js";
import { keccak256V1 as keccak256 } from "./keccak.js";
import type {
  CanonicalCustomGraphLaunchV1,
  LaunchPermitV1,
} from "./abi-codec.js";
import {
  canonicalRawSignatureV1,
  encodeErc1271CallV1,
  encodePermitDigestCallV1,
} from "./abi-codec.js";
import { normalizePendingNonceV1 } from "./browser-action.js";
import {
  PRODUCTION_ROUTER_SELF_SERVICE_BINDING_V1 as BINDING,
  type EvmAddressV1,
  type EvmBytes32V1,
  type EvmHexV1,
} from "./production-binding.js";

const ZERO_WORD = `0x${"00".repeat(32)}` as EvmBytes32V1;
const ZERO_TWO_WORDS = `0x${"00".repeat(64)}` as EvmHexV1;
const ZERO_LAUNCH_STAMP = `0x${"00".repeat(32 * 14)}` as EvmHexV1;

export interface RouterReadRpcProviderV1 {
  readonly providerId: string;
  /** Distinct operator/credential/network trust domain, not only a URL. */
  readonly trustDomain: string;
  request(method: string, params: readonly unknown[]): Promise<unknown>;
}

/** Provider adapters use this only for an authenticated JSON-RPC execution
 * revert. Transport, timeout, parse, and provider-authentication failures must
 * remain their original errors and therefore fail the authority closed. */
export class RouterRpcExecutionRevertV1 extends Error {
  constructor(message = "EVM execution reverted") {
    super(message);
    this.name = "RouterRpcExecutionRevertV1";
    Object.freeze(this);
  }
}

export interface CommonFinalizedAnchorV1 {
  readonly schemaVersion: "programmable.router-common-finalized-anchor.v1";
  readonly chainId: "1";
  readonly blockNumber: EvmHexV1;
  readonly blockHash: EvmBytes32V1;
  readonly timestamp: string;
  readonly providerIds: readonly [string, string];
  readonly anchorHash: Sha256Digest;
}

export interface RouterChainClockV1 {
  readonly minimumTimestamp: string;
  readonly maximumTimestamp: string;
  readonly providerTimestamps: readonly [string, string];
}

export interface RouterReadAuthorityBindingV1 {
  readonly schemaVersion: "programmable.router-read-authority-binding.v1";
  readonly chainId: "1";
  readonly providers: readonly [
    Readonly<{ providerId: string; trustDomain: string }>,
    Readonly<{ providerId: string; trustDomain: string }>,
  ];
  readonly bindingHash: Sha256Digest;
}

export type RouterPreviousTransactionDispositionV1 =
  | "not-submitted"
  | "absent-after-finalized-deadline"
  | "finalized-reverted";

export interface RouterPreviousPermitObservationV1 {
  readonly previousPermitDeadline: string | null;
  readonly transaction: null | Readonly<{
    transactionHash: EvmBytes32V1;
    disposition: Exclude<RouterPreviousTransactionDispositionV1, "not-submitted">;
    blockNumber: EvmHexV1 | null;
    blockHash: EvmBytes32V1 | null;
  }>;
}

export interface RouterLaunchUnconsumedEvidenceV1 {
  readonly schemaVersion: "programmable.router-launch-unconsumed-evidence.v1";
  readonly chainId: "1";
  readonly router: EvmAddressV1;
  readonly routerRuntimeKeccak256: EvmBytes32V1;
  readonly graphFactory: EvmAddressV1;
  readonly graphFactoryRuntimeKeccak256: EvmBytes32V1;
  readonly launchId: EvmBytes32V1;
  readonly token: EvmAddressV1;
  readonly poolId: EvmBytes32V1;
  readonly routeNonce: EvmBytes32V1;
  readonly graphAuthorizationKey: EvmBytes32V1;
  readonly targetAccounts: readonly EvmAddressV1[];
  readonly componentAccounts: readonly EvmAddressV1[];
  readonly commonFinalizedAnchorHash: Sha256Digest;
  readonly runtimeBindings: "matched-finalized-and-latest";
  readonly targetRuntimeState: "empty-finalized-and-latest";
  readonly graphAuthorizationState: "unconsumed-finalized-and-latest";
  readonly launchStampState: "empty-finalized-and-latest";
  readonly tokenIndexState: "empty-finalized-and-latest";
  readonly poolIndexState: "empty-finalized-and-latest";
  readonly componentIndexState: "empty-finalized-and-latest";
  readonly componentProofState: "empty-finalized-and-latest";
  readonly previousPermit: Readonly<RouterPreviousPermitObservationV1>;
  readonly evidenceHash: Sha256Digest;
}

export interface RouterPreflightEvidenceV1 {
  readonly schemaVersion: "programmable.router-self-service-preflight.v1";
  readonly finalizedAnchor: Readonly<CommonFinalizedAnchorV1>;
  readonly chainClock: Readonly<RouterChainClockV1>;
  readonly pendingNonce: string;
  readonly targetCount: number;
  readonly unconsumed: Readonly<RouterLaunchUnconsumedEvidenceV1>;
  readonly bindingHash: Sha256Digest;
}

export interface RouterSelfServiceReadAuthorityV1 {
  verifyProductionPreflight(input: Readonly<{
    launch: CanonicalCustomGraphLaunchV1;
    launchWallet: EvmAddressV1;
    previousPermit?: Readonly<{
      deadline: string;
      transactionHash: EvmBytes32V1 | null;
      expectedDisposition: RouterPreviousTransactionDispositionV1;
    }> | null;
  }>): Promise<Readonly<RouterPreflightEvidenceV1>>;
  verifyPermitDigest(
    permit: LaunchPermitV1,
    expectedDigest: EvmBytes32V1,
    blockTag: string,
  ): Promise<void>;
  selectValidSafeSignature(input: Readonly<{
    permitDigest: EvmBytes32V1;
    rawSignature65: EvmHexV1;
  }>): Promise<EvmHexV1>;
  simulateExactLaunch(input: Readonly<{
    from: EvmAddressV1;
    data: EvmHexV1;
    value: EvmHexV1;
    expectedStampHash: EvmBytes32V1;
  }>): Promise<void>;
}

export interface RouterFinalityReadAuthorityV1 {
  collectCommonFinalizedAnchor(): Promise<Readonly<CommonFinalizedAnchorV1>>;
  readConsensus(method: string, params: readonly unknown[]): Promise<unknown>;
  ethCallConsensus(
    transaction: Readonly<Record<string, EvmHexV1>>,
    blockTag: string,
  ): Promise<EvmHexV1>;
}

export interface RouterProductionRuntimeReadAuthorityV1 {
  verifyProductionRuntimeBindings(): Promise<Readonly<CommonFinalizedAnchorV1>>;
}

export interface RouterCompilerReadAuthorityV1 extends RouterFinalityReadAuthorityV1 {
  binding(): Readonly<RouterReadAuthorityBindingV1>;
}

export class DualProviderRouterReadAdapterV1 implements
  RouterSelfServiceReadAuthorityV1, RouterFinalityReadAuthorityV1,
  RouterCompilerReadAuthorityV1, RouterProductionRuntimeReadAuthorityV1 {
  readonly #providers: readonly [RouterReadRpcProviderV1, RouterReadRpcProviderV1];

  constructor(providers: readonly [RouterReadRpcProviderV1, RouterReadRpcProviderV1]) {
    const [left, right] = providers;
    for (const provider of providers) {
      boundedId(provider.providerId, "RPC provider id");
      boundedId(provider.trustDomain, "RPC trust domain");
    }
    if (left.providerId === right.providerId || left.trustDomain === right.trustDomain) {
      throw new TypeError("Router RPC providers are not independent");
    }
    this.#providers = Object.freeze(providers);
    Object.freeze(this);
  }

  binding(): Readonly<RouterReadAuthorityBindingV1> {
    const providers = this.#providers.map(({ providerId, trustDomain }) =>
      Object.freeze({ providerId, trustDomain })).sort((left, right) =>
      Buffer.compare(Buffer.from(left.providerId, "utf8"), Buffer.from(right.providerId, "utf8")));
    const core = {
      schemaVersion: "programmable.router-read-authority-binding.v1" as const,
      chainId: "1" as const,
      providers: providers as unknown as RouterReadAuthorityBindingV1["providers"],
    };
    return deepFreeze({
      ...core,
      bindingHash: canonicalSha256(core.schemaVersion, core),
    });
  }

  async collectCommonFinalizedAnchor(): Promise<Readonly<CommonFinalizedAnchorV1>> {
    await this.#assertMainnet();
    const finalized = await Promise.all(this.#providers.map((provider) =>
      provider.request("eth_getBlockByNumber", ["finalized", false])));
    const blocks = finalized.map((value) => rpcBlock(value, "finalized block"));
    const commonNumber = blocks.reduce(
      (minimum, block) => BigInt(block.number) < minimum ? BigInt(block.number) : minimum,
      BigInt(blocks[0]!.number),
    );
    const minimumFinalizedBlock = BigInt(BINDING.router.deployment.firstFinalizedEvidenceBlock);
    if (commonNumber < minimumFinalizedBlock) {
      throw new TypeError("common finality predates the Router finalization proof");
    }
    const tag = quantity(commonNumber);
    const common = await Promise.all(this.#providers.map((provider) =>
      provider.request("eth_getBlockByNumber", [tag, false])));
    const observed = common.map((value) => rpcBlock(value, "common finalized block"));
    if (observed[0]!.hash !== observed[1]!.hash || observed.some((block) => block.number !== tag)) {
      throw new TypeError("RPC providers disagree on the common finalized block");
    }
    const anchorCore = {
      schemaVersion: "programmable.router-common-finalized-anchor.v1" as const,
      chainId: "1" as const,
      blockNumber: tag,
      blockHash: observed[0]!.hash,
      timestamp: BigInt(observed[0]!.timestamp).toString(10),
      providerIds: [this.#providers[0].providerId, this.#providers[1].providerId] as const,
    };
    return deepFreeze({
      ...anchorCore,
      anchorHash: canonicalSha256("programmable.router-common-finalized-anchor.v1", anchorCore),
    });
  }

  async observeChainClock(): Promise<Readonly<RouterChainClockV1>> {
    const values = await Promise.all(this.#providers.map((provider) =>
      provider.request("eth_getBlockByNumber", ["latest", false])));
    const timestamps = values.map((value) => BigInt(rpcBlock(value, "latest block").timestamp));
    const minimum = timestamps[0]! < timestamps[1]! ? timestamps[0]! : timestamps[1]!;
    const maximum = timestamps[0]! > timestamps[1]! ? timestamps[0]! : timestamps[1]!;
    if (maximum - minimum > 120n) throw new TypeError("RPC provider chain clocks diverge by more than 120 seconds");
    return deepFreeze({
      minimumTimestamp: minimum.toString(10),
      maximumTimestamp: maximum.toString(10),
      providerTimestamps: [timestamps[0]!.toString(10), timestamps[1]!.toString(10)] as const,
    });
  }

  async verifyProductionRuntimeBindings(): Promise<Readonly<CommonFinalizedAnchorV1>> {
    const finalizedAnchor = await this.collectCommonFinalizedAnchor();
    await this.#verifyRuntimeAndBindings(finalizedAnchor.blockNumber);
    await this.#verifyRuntimeAndBindings("latest");
    return finalizedAnchor;
  }

  async verifyProductionPreflight(input: Readonly<{
    launch: CanonicalCustomGraphLaunchV1;
    launchWallet: EvmAddressV1;
    previousPermit?: Readonly<{
      deadline: string;
      transactionHash: EvmBytes32V1 | null;
      expectedDisposition: RouterPreviousTransactionDispositionV1;
    }> | null;
  }>): Promise<Readonly<RouterPreflightEvidenceV1>> {
    const [finalizedAnchor, chainClock] = await Promise.all([
      this.collectCommonFinalizedAnchor(),
      this.observeChainClock(),
    ]);
    const tags = [finalizedAnchor.blockNumber, "latest"] as const;
    for (const tag of tags) await this.#verifyRuntimeAndBindings(tag);

    const targetAddresses = input.launch.plan.route.expectedOutputs.map(({ account }) => account);
    const graphAuthorizationKey = graphAuthorizationKeyV1(input.launch);
    for (const tag of tags) {
      const targetCodes = await Promise.all(targetAddresses.map((account) =>
        this.readConsensus("eth_getCode", [account, tag])));
      const consumed = await this.ethCallConsensus({
        to: BINDING.graphFactory.address,
        data: joinHex(BINDING.selectors.consumedGraphAuthorization, graphAuthorizationKey),
      }, tag);
      const existingLaunchStamp = await this.ethCallConsensus({
        to: BINDING.router.address,
        data: joinHex(BINDING.selectors.launchStamp, input.launch.plan.stampRequest.launchId),
      }, tag);
      assertRouterLaunchVacancyObservationsV1({
        targetCodes,
        consumedGraphAuthorization: consumed,
        launchStamp: existingLaunchStamp,
      });
      await this.#requireZeroRouterRead(
        BINDING.selectors.launchIdByToken,
        [addressWord(input.launch.plan.stampRequest.token)],
        "token launch id",
        tag,
      );
      await this.#requireZeroRouterRead(
        BINDING.selectors.launchIdByPool,
        [addressWord(BINDING.poolManager.address), word(input.launch.poolId)],
        "pool launch id",
        tag,
      );
      for (const component of input.launch.plan.stampRequest.components) {
        await this.#requireZeroRouterRead(
          BINDING.selectors.launchIdByComponent,
          [addressWord(component.account)],
          "component launch id",
          tag,
        );
        const proof = await this.ethCallConsensus({
          to: BINDING.router.address,
          data: joinHex(BINDING.selectors.stampProof, addressWord(component.account)),
        }, tag);
        if (proof !== ZERO_TWO_WORDS) throw new TypeError("component already has a Router stamp proof");
      }
    }

    const previousPermit = await observePreviousRouterPermitV1(
      input.previousPermit ?? null,
      finalizedAnchor,
      (method, params) => this.readConsensus(method, params),
    );
    const unconsumedCore = {
      schemaVersion: "programmable.router-launch-unconsumed-evidence.v1" as const,
      chainId: BINDING.chain.chainIdDecimal as "1",
      router: BINDING.router.address,
      routerRuntimeKeccak256: BINDING.router.runtimeKeccak256,
      graphFactory: BINDING.graphFactory.address,
      graphFactoryRuntimeKeccak256: BINDING.graphFactory.runtimeKeccak256,
      launchId: input.launch.plan.stampRequest.launchId,
      token: input.launch.plan.stampRequest.token,
      poolId: input.launch.poolId,
      routeNonce: input.launch.plan.route.routeNonce,
      graphAuthorizationKey,
      targetAccounts: input.launch.plan.route.expectedOutputs.map(({ account }) => account),
      componentAccounts: input.launch.plan.stampRequest.components.map(({ account }) => account),
      commonFinalizedAnchorHash: finalizedAnchor.anchorHash,
      runtimeBindings: "matched-finalized-and-latest" as const,
      targetRuntimeState: "empty-finalized-and-latest" as const,
      graphAuthorizationState: "unconsumed-finalized-and-latest" as const,
      launchStampState: "empty-finalized-and-latest" as const,
      tokenIndexState: "empty-finalized-and-latest" as const,
      poolIndexState: "empty-finalized-and-latest" as const,
      componentIndexState: "empty-finalized-and-latest" as const,
      componentProofState: "empty-finalized-and-latest" as const,
      previousPermit,
    };
    const unconsumed = deepFreeze({
      ...unconsumedCore,
      evidenceHash: canonicalSha256(unconsumedCore.schemaVersion, unconsumedCore),
    });
    const pending = await Promise.all(this.#providers.map((provider) =>
      provider.request("eth_getTransactionCount", [input.launchWallet, "pending"])));
    const pendingNonce = normalizePendingNonceV1(pending[0]);
    if (pendingNonce !== normalizePendingNonceV1(pending[1])) {
      throw new TypeError("RPC providers disagree on the launch wallet pending nonce");
    }
    const evidence = {
      schemaVersion: "programmable.router-self-service-preflight.v1" as const,
      finalizedAnchor,
      chainClock,
      pendingNonce,
      targetCount: targetAddresses.length,
      unconsumed,
    };
    return deepFreeze({
      ...evidence,
      bindingHash: canonicalSha256("programmable.router-self-service-preflight.v1", evidence),
    });
  }

  async verifyPermitDigest(
    permit: LaunchPermitV1,
    expectedDigest: EvmBytes32V1,
    blockTag: string,
  ): Promise<void> {
    const result = await this.ethCallConsensus({
      to: BINDING.router.address,
      data: encodePermitDigestCallV1(permit),
    }, blockTag);
    if (result !== expectedDigest) throw new TypeError("local Router permit digest disagrees with finalized bytecode");
  }

  async selectValidSafeSignature(input: Readonly<{
    permitDigest: EvmBytes32V1;
    rawSignature65: EvmHexV1;
  }>): Promise<EvmHexV1> {
    const signature = canonicalRawSignatureV1(input.rawSignature65);
    const outcomes = await this.#ethCallOutcomes({
      to: BINDING.permitAuthoritySafe.address,
      data: encodeErc1271CallV1(input.permitDigest, signature),
    }, "latest");
    const magic = outcomes.filter((outcome) =>
      outcome.state === "returned"
      && outcome.value === BINDING.permitAuthoritySafe.erc1271MagicWord).length;
    if (magic === 1) throw new TypeError("RPC providers disagree on Safe ERC-1271 owner signature");
    if (magic !== 2) throw new TypeError("Safe ERC-1271 rejected the manual owner signature");
    const mutated = flipDigestBit(input.permitDigest);
    const negative = await this.#ethCallOutcomes({
      to: BINDING.permitAuthoritySafe.address,
      data: encodeErc1271CallV1(mutated, signature),
    }, "latest");
    if (negative.some((outcome) =>
      outcome.state === "returned"
      && outcome.value === BINDING.permitAuthoritySafe.erc1271MagicWord)) {
      throw new TypeError("Safe ERC-1271 accepted a one-bit-mutated permit digest");
    }
    for (const outcome of negative) {
      if (outcome.state === "returned" && !/^0x[0-9a-f]{64}$/u.test(outcome.value)) {
        throw new TypeError("Safe ERC-1271 negative result is malformed");
      }
    }
    return signature;
  }

  async simulateExactLaunch(input: Readonly<{
    from: EvmAddressV1;
    data: EvmHexV1;
    value: EvmHexV1;
    expectedStampHash: EvmBytes32V1;
  }>): Promise<void> {
    const result = await this.ethCallConsensus({
      from: input.from,
      to: BINDING.router.address,
      data: input.data,
      value: input.value,
    }, "latest");
    if (result !== input.expectedStampHash) {
      throw new TypeError("exact launch simulation did not return the expected stamp hash");
    }
  }

  async ethCallConsensus(
    transaction: Readonly<Record<string, EvmHexV1>>,
    blockTag: string,
  ): Promise<EvmHexV1> {
    return hex(await this.readConsensus("eth_call", [transaction, blockTag]), "eth_call result");
  }

  async readConsensus(method: string, params: readonly unknown[]): Promise<unknown> {
    const values = await Promise.all(this.#providers.map((provider) => provider.request(method, params)));
    if (canonicalizeJson(values[0]) !== canonicalizeJson(values[1])) {
      throw new TypeError(`RPC providers disagree on ${method}`);
    }
    return values[0];
  }

  async #assertMainnet(): Promise<void> {
    const values = await Promise.all(this.#providers.map((provider) => provider.request("eth_chainId", [])));
    if (values.some((value) => value !== BINDING.chain.chainIdHex)) {
      throw new TypeError("Router RPC provider is not bound to Ethereum mainnet");
    }
  }

  async #ethCallOutcomes(
    transaction: Readonly<Record<string, EvmHexV1>>,
    blockTag: string,
  ): Promise<readonly [
    Readonly<{ state: "returned"; value: EvmHexV1 }> | Readonly<{ state: "reverted" }>,
    Readonly<{ state: "returned"; value: EvmHexV1 }> | Readonly<{ state: "reverted" }>,
  ]> {
    const read = async (provider: RouterReadRpcProviderV1) => {
      try {
        return Object.freeze({
          state: "returned" as const,
          value: hex(await provider.request("eth_call", [transaction, blockTag]), "eth_call result"),
        });
      } catch (error) {
        if (!(error instanceof RouterRpcExecutionRevertV1)) throw error;
        return Object.freeze({ state: "reverted" as const });
      }
    };
    return Object.freeze(await Promise.all([
      read(this.#providers[0]),
      read(this.#providers[1]),
    ]));
  }

  async #verifyRuntimeAndBindings(blockTag: string): Promise<void> {
    const runtimeBindings = [
      [BINDING.router.address, BINDING.router.runtimeKeccak256, "Router"],
      [BINDING.permitAuthoritySafe.address, BINDING.permitAuthoritySafe.runtimeKeccak256, "Safe"],
      [BINDING.graphFactory.address, BINDING.graphFactory.runtimeKeccak256, "GraphFactory"],
      [BINDING.poolManager.address, BINDING.poolManager.runtimeKeccak256, "PoolManager"],
    ] as const;
    for (const [account, expectedHash, label] of runtimeBindings) {
      const code = hex(await this.readConsensus("eth_getCode", [account, blockTag]), `${label} runtime`);
      if (code === "0x" || keccak256(Buffer.from(code.slice(2), "hex")) !== expectedHash) {
        throw new TypeError(`${label} runtime code hash drifted`);
      }
    }
    const routerWords = [
      [BINDING.selectors.chainId, word(quantityWord(1n)), "Router chain id"],
      [BINDING.selectors.permitAuthority, addressWord(BINDING.permitAuthoritySafe.address), "Router Safe"],
      [BINDING.selectors.graphFactory, addressWord(BINDING.graphFactory.address), "Router GraphFactory"],
      [BINDING.selectors.poolManager, addressWord(BINDING.poolManager.address), "Router PoolManager"],
      [BINDING.selectors.permitAuthorityRuntime, word(BINDING.permitAuthoritySafe.runtimeKeccak256), "Router Safe runtime"],
      [BINDING.selectors.graphFactoryRuntime, word(BINDING.graphFactory.runtimeKeccak256), "Router GraphFactory runtime"],
      [BINDING.selectors.poolManagerRuntime, word(BINDING.poolManager.runtimeKeccak256), "Router PoolManager runtime"],
    ] as const;
    for (const [selector, expected, label] of routerWords) {
      const observed = await this.ethCallConsensus({ to: BINDING.router.address, data: selector }, blockTag);
      if (observed !== expected) throw new TypeError(`${label} immutable binding drifted`);
    }
    await this.#verifySafeState(blockTag);
  }

  async #verifySafeState(blockTag: string): Promise<void> {
    const masterCopy = await this.ethCallConsensus({
      to: BINDING.permitAuthoritySafe.address,
      data: BINDING.selectors.safeMasterCopy,
    }, blockTag);
    if (masterCopy !== addressWord(BINDING.permitAuthoritySafe.masterCopy)) {
      throw new TypeError("Safe master-copy binding drifted");
    }
    const threshold = await this.ethCallConsensus({
      to: BINDING.permitAuthoritySafe.address,
      data: BINDING.selectors.safeThreshold,
    }, blockTag);
    if (threshold !== word(quantityWord(BigInt(BINDING.permitAuthoritySafe.threshold)))) {
      throw new TypeError("Safe threshold drifted");
    }
    const ownersRaw = await this.ethCallConsensus({
      to: BINDING.permitAuthoritySafe.address,
      data: BINDING.selectors.safeOwners,
    }, blockTag);
    const owners = decodeAddressArray(ownersRaw, "Safe owners");
    assertManualSafeOwnerSetV1(owners);
    const versionRaw = await this.ethCallConsensus({
      to: BINDING.permitAuthoritySafe.address,
      data: BINDING.selectors.safeVersion,
    }, blockTag);
    if (decodeAbiString(versionRaw, "Safe version") !== BINDING.permitAuthoritySafe.version) {
      throw new TypeError("Safe version drifted");
    }
    const fallback = hex(await this.readConsensus("eth_getStorageAt", [
      BINDING.permitAuthoritySafe.address,
      BINDING.permitAuthoritySafe.fallbackStorageSlot,
      blockTag,
    ]), "Safe fallback-handler slot");
    if (fallback !== addressWord(BINDING.permitAuthoritySafe.fallbackHandler)) {
      throw new TypeError("Safe fallback-handler binding drifted");
    }
    const guard = hex(await this.readConsensus("eth_getStorageAt", [
      BINDING.permitAuthoritySafe.address,
      BINDING.permitAuthoritySafe.guardStorageSlot,
      blockTag,
    ]), "Safe guard slot");
    if (guard !== addressWord(BINDING.permitAuthoritySafe.guard)) {
      throw new TypeError("Safe guard binding drifted");
    }
    const modules = await this.ethCallConsensus({
      to: BINDING.permitAuthoritySafe.address,
      data: joinHex(
        BINDING.selectors.safeModulesPaginated,
        addressWord(BINDING.permitAuthoritySafe.moduleSentinel),
        quantityWord(100n),
      ),
    }, blockTag);
    const expectedModules = joinHex(
      quantityWord(64n),
      addressWord(BINDING.permitAuthoritySafe.moduleSentinel),
      quantityWord(0n),
    );
    if (BINDING.permitAuthoritySafe.modules.length !== 0 || modules !== expectedModules) {
      throw new TypeError("Safe module set drifted");
    }
  }

  async #requireZeroRouterRead(
    selector: EvmHexV1,
    words: readonly EvmHexV1[],
    label: string,
    blockTag: string,
  ): Promise<void> {
    const observed = await this.ethCallConsensus({
      to: BINDING.router.address,
      data: joinHex(selector, ...words),
    }, blockTag);
    if (observed !== ZERO_WORD) throw new TypeError(`${label} is already occupied`);
  }
}

export function assertRouterReadAuthorityBindingV1(
  raw: RouterReadAuthorityBindingV1,
): Readonly<RouterReadAuthorityBindingV1> {
  assertExactKeys(raw, [
    "bindingHash", "chainId", "providers", "schemaVersion",
  ], "Router read authority binding");
  if (
    raw.schemaVersion !== "programmable.router-read-authority-binding.v1"
    || raw.chainId !== BINDING.chain.chainIdDecimal
    || !Array.isArray(raw.providers)
    || raw.providers.length !== 2
  ) throw new TypeError("Router read authority binding shape is invalid");
  const providers = raw.providers.map((value, index) => {
    assertExactKeys(value, ["providerId", "trustDomain"], `Router provider ${index}`);
    boundedId(value.providerId, `Router provider ${index} id`);
    boundedId(value.trustDomain, `Router provider ${index} trust domain`);
    return Object.freeze({ providerId: value.providerId, trustDomain: value.trustDomain });
  }).sort((left, right) =>
    Buffer.compare(Buffer.from(left.providerId, "utf8"), Buffer.from(right.providerId, "utf8")));
  if (
    providers[0]!.providerId === providers[1]!.providerId
    || providers[0]!.trustDomain === providers[1]!.trustDomain
  ) throw new TypeError("Router read authority providers are not independent");
  const core = {
    schemaVersion: "programmable.router-read-authority-binding.v1" as const,
    chainId: "1" as const,
    providers: providers as unknown as RouterReadAuthorityBindingV1["providers"],
  };
  if (raw.bindingHash !== canonicalSha256(core.schemaVersion, core)) {
    throw new TypeError("Router read authority binding hash is invalid");
  }
  return deepFreeze({ ...core, bindingHash: raw.bindingHash });
}

export function assertRouterLaunchVacancyObservationsV1(input: Readonly<{
  targetCodes: readonly unknown[];
  consumedGraphAuthorization: unknown;
  launchStamp: unknown;
}>): void {
  const targetCodes = input.targetCodes.map((value, index) =>
    hex(value, `CustomGraph target ${index} runtime`));
  const consumed = hex(input.consumedGraphAuthorization, "CustomGraph authorization state");
  const launchStamp = hex(input.launchStamp, "Router launch stamp state");
  if (targetCodes.length < 1 || targetCodes.length > 16) {
    throw new TypeError("CustomGraph target runtime observation count is invalid");
  }
  if (targetCodes.some((code) => code !== "0x")) {
    throw new TypeError("one or more CustomGraph target addresses already contain code");
  }
  if (consumed !== ZERO_WORD) {
    throw new TypeError("CustomGraph authorization key is already consumed");
  }
  if (launchStamp !== ZERO_LAUNCH_STAMP) {
    throw new TypeError("launch id already has a Router stamp record");
  }
}

export async function observePreviousRouterPermitV1(
  raw: Readonly<{
    deadline: string;
    transactionHash: EvmBytes32V1 | null;
    expectedDisposition: RouterPreviousTransactionDispositionV1;
  }> | null,
  finalizedAnchor: Readonly<CommonFinalizedAnchorV1>,
  readConsensus: (method: string, params: readonly unknown[]) => Promise<unknown>,
): Promise<Readonly<RouterPreviousPermitObservationV1>> {
  const anchor = assertCommonFinalizedAnchorV1(finalizedAnchor);
  if (raw === null) {
    return deepFreeze({ previousPermitDeadline: null, transaction: null });
  }
  const deadline = decimalString(raw.deadline, "previous Router permit deadline");
  if (BigInt(anchor.timestamp) <= BigInt(deadline)) {
    throw new TypeError("previous Router permit deadline is not behind common finality");
  }
  if (raw.expectedDisposition === "not-submitted") {
    if (raw.transactionHash !== null) {
      throw new TypeError("not-submitted previous permit unexpectedly has a transaction hash");
    }
    return deepFreeze({ previousPermitDeadline: deadline, transaction: null });
  }
  const transactionHash = bytes32(raw.transactionHash, "previous Router transaction hash");
  const receiptValue = await readConsensus("eth_getTransactionReceipt", [transactionHash]);
  if (receiptValue === null) {
    const transactionValue = await readConsensus("eth_getTransactionByHash", [transactionHash]);
    if (transactionValue !== null) {
      throw new TypeError("previous Router transaction is still known without a finalized receipt");
    }
    if (raw.expectedDisposition !== "absent-after-finalized-deadline") {
      throw new TypeError("previous Router transaction disposition is not the expected finalized revert");
    }
    return deepFreeze({
      previousPermitDeadline: deadline,
      transaction: {
        transactionHash,
        disposition: "absent-after-finalized-deadline" as const,
        blockNumber: null,
        blockHash: null,
      },
    });
  }
  const receipt = rpcObject(receiptValue, "previous Router transaction receipt");
  const status = rpcQuantity(receipt.status, "previous Router receipt status");
  if (status === "0x1") {
    throw new TypeError("previous Router transaction succeeded and cannot be reissued");
  }
  if (status !== "0x0" || raw.expectedDisposition !== "finalized-reverted") {
    throw new TypeError("previous Router transaction disposition is invalid");
  }
  const blockNumber = rpcQuantity(receipt.blockNumber, "previous Router receipt block number");
  const blockHash = bytes32(receipt.blockHash, "previous Router receipt block hash");
  if (
    bytes32(receipt.transactionHash, "previous Router receipt transaction hash") !== transactionHash
    || BigInt(blockNumber) > BigInt(anchor.blockNumber)
  ) throw new TypeError("previous Router reverted receipt is not commonly finalized");
  const canonicalBlock = rpcObject(await readConsensus(
    "eth_getBlockByNumber",
    [blockNumber, false],
  ), "previous Router receipt block");
  if (
    rpcQuantity(canonicalBlock.number, "previous Router block number") !== blockNumber
    || bytes32(canonicalBlock.hash, "previous Router block hash") !== blockHash
  ) throw new TypeError("previous Router reverted receipt block is not canonical");
  return deepFreeze({
    previousPermitDeadline: deadline,
    transaction: {
      transactionHash,
      disposition: "finalized-reverted" as const,
      blockNumber,
      blockHash,
    },
  });
}

export function assertManualSafeOwnerSetV1(
  owners: readonly EvmAddressV1[],
): void {
  const expectedOwners = new Set([BINDING.permitAuthoritySafe.manualOwner]);
  if (
    owners.length !== expectedOwners.size
    || new Set(owners).size !== owners.length
    || owners.some((owner) => !expectedOwners.has(owner))
  ) throw new TypeError("Safe owner set drifted");
}

export function assertCommonFinalizedAnchorV1(
  raw: unknown,
): Readonly<CommonFinalizedAnchorV1> {
  assertExactKeys(raw, [
    "anchorHash", "blockHash", "blockNumber", "chainId", "providerIds", "schemaVersion",
    "timestamp",
  ], "Router common finalized anchor");
  if (
    raw.schemaVersion !== "programmable.router-common-finalized-anchor.v1"
    || raw.chainId !== BINDING.chain.chainIdDecimal
    || !Array.isArray(raw.providerIds)
    || raw.providerIds.length !== 2
    || raw.providerIds.some((providerId) => typeof providerId !== "string")
  ) throw new TypeError("Router common finalized anchor shape is invalid");
  const providerIds = raw.providerIds as [string, string];
  providerIds.forEach((providerId) => boundedId(providerId, "RPC provider id"));
  if (providerIds[0] === providerIds[1]) {
    throw new TypeError("Router common finalized anchor providers are not distinct");
  }
  const core = {
    schemaVersion: "programmable.router-common-finalized-anchor.v1" as const,
    chainId: "1" as const,
    blockNumber: rpcQuantity(raw.blockNumber, "finalized anchor block number"),
    blockHash: bytes32(raw.blockHash, "finalized anchor block hash"),
    timestamp: decimalString(raw.timestamp, "finalized anchor timestamp"),
    providerIds: [providerIds[0], providerIds[1]] as const,
  };
  if (raw.anchorHash !== canonicalSha256(
    "programmable.router-common-finalized-anchor.v1",
    core,
  )) throw new TypeError("Router common finalized anchor hash is invalid");
  return deepFreeze({ ...core, anchorHash: raw.anchorHash as Sha256Digest });
}

export function assertRouterPreflightEvidenceV1(
  raw: unknown,
  launch?: Readonly<CanonicalCustomGraphLaunchV1>,
): Readonly<RouterPreflightEvidenceV1> {
  assertExactKeys(raw, [
    "bindingHash", "chainClock", "finalizedAnchor", "pendingNonce", "schemaVersion",
    "targetCount", "unconsumed",
  ], "Router self-service preflight");
  if (raw.schemaVersion !== "programmable.router-self-service-preflight.v1") {
    throw new TypeError("Router self-service preflight schema is invalid");
  }
  assertExactKeys(raw.chainClock, [
    "maximumTimestamp", "minimumTimestamp", "providerTimestamps",
  ], "Router chain clock");
  if (!Array.isArray(raw.chainClock.providerTimestamps)
    || raw.chainClock.providerTimestamps.length !== 2) {
    throw new TypeError("Router chain clock provider timestamps are invalid");
  }
  const providerTimestamps = raw.chainClock.providerTimestamps.map((value, index) =>
    decimalString(value, `Router provider ${index} timestamp`)) as [string, string];
  const minimum = BigInt(providerTimestamps[0]) < BigInt(providerTimestamps[1])
    ? providerTimestamps[0]
    : providerTimestamps[1];
  const maximum = BigInt(providerTimestamps[0]) > BigInt(providerTimestamps[1])
    ? providerTimestamps[0]
    : providerTimestamps[1];
  const chainClock = {
    minimumTimestamp: decimalString(raw.chainClock.minimumTimestamp, "Router minimum timestamp"),
    maximumTimestamp: decimalString(raw.chainClock.maximumTimestamp, "Router maximum timestamp"),
    providerTimestamps: [providerTimestamps[0], providerTimestamps[1]] as const,
  };
  if (chainClock.minimumTimestamp !== minimum || chainClock.maximumTimestamp !== maximum) {
    throw new TypeError("Router chain clock bounds do not match provider timestamps");
  }
  if (BigInt(maximum) - BigInt(minimum) > 120n) {
    throw new TypeError("Router provider chain clocks diverge by more than 120 seconds");
  }
  const pendingNonce = decimalString(raw.pendingNonce, "Router pending nonce");
  const targetCount = raw.targetCount;
  if (!Number.isSafeInteger(targetCount) || (targetCount as number) < 1 || (targetCount as number) > 16) {
    throw new TypeError("Router preflight target count is invalid");
  }
  const finalizedAnchor = assertCommonFinalizedAnchorV1(raw.finalizedAnchor);
  const unconsumed = assertRouterLaunchUnconsumedEvidenceV1(raw.unconsumed, launch);
  if (unconsumed.commonFinalizedAnchorHash !== finalizedAnchor.anchorHash) {
    throw new TypeError("Router unconsumed evidence does not bind the common finalized anchor");
  }
  const evidence = {
    schemaVersion: "programmable.router-self-service-preflight.v1" as const,
    finalizedAnchor,
    chainClock,
    pendingNonce,
    targetCount: targetCount as number,
    unconsumed,
  };
  if (raw.bindingHash !== canonicalSha256(
    "programmable.router-self-service-preflight.v1",
    evidence,
  )) throw new TypeError("Router self-service preflight binding hash is invalid");
  return deepFreeze({ ...evidence, bindingHash: raw.bindingHash as Sha256Digest });
}

export function assertRouterLaunchUnconsumedEvidenceV1(
  raw: unknown,
  launch?: Readonly<CanonicalCustomGraphLaunchV1>,
): Readonly<RouterLaunchUnconsumedEvidenceV1> {
  assertExactKeys(raw, [
    "chainId", "commonFinalizedAnchorHash", "componentAccounts", "componentIndexState",
    "componentProofState", "evidenceHash", "graphFactory", "graphFactoryRuntimeKeccak256",
    "graphAuthorizationKey", "graphAuthorizationState", "launchId", "launchStampState",
    "poolId", "poolIndexState", "previousPermit",
    "routeNonce", "router", "routerRuntimeKeccak256", "runtimeBindings", "schemaVersion",
    "targetAccounts", "targetRuntimeState", "token", "tokenIndexState",
  ], "Router launch unconsumed evidence");
  if (
    raw.schemaVersion !== "programmable.router-launch-unconsumed-evidence.v1"
    || raw.chainId !== BINDING.chain.chainIdDecimal
    || raw.router !== BINDING.router.address
    || raw.routerRuntimeKeccak256 !== BINDING.router.runtimeKeccak256
    || raw.graphFactory !== BINDING.graphFactory.address
    || raw.graphFactoryRuntimeKeccak256 !== BINDING.graphFactory.runtimeKeccak256
    || raw.runtimeBindings !== "matched-finalized-and-latest"
    || raw.targetRuntimeState !== "empty-finalized-and-latest"
    || raw.graphAuthorizationState !== "unconsumed-finalized-and-latest"
    || raw.launchStampState !== "empty-finalized-and-latest"
    || raw.tokenIndexState !== "empty-finalized-and-latest"
    || raw.poolIndexState !== "empty-finalized-and-latest"
    || raw.componentIndexState !== "empty-finalized-and-latest"
    || raw.componentProofState !== "empty-finalized-and-latest"
    || !Array.isArray(raw.targetAccounts)
    || !Array.isArray(raw.componentAccounts)
  ) throw new TypeError("Router launch unconsumed evidence binding is invalid");
  const targetAccounts = raw.targetAccounts.map((value, index) =>
    rpcAddress(value, `Router target account ${index}`));
  const componentAccounts = raw.componentAccounts.map((value, index) =>
    rpcAddress(value, `Router component account ${index}`));
  if (
    targetAccounts.length < 1 || targetAccounts.length > 16
    || componentAccounts.length < 1 || componentAccounts.length > 16
    || new Set(targetAccounts).size !== targetAccounts.length
    || new Set(componentAccounts).size !== componentAccounts.length
  ) throw new TypeError("Router launch unconsumed account set is invalid");
  assertExactKeys(raw.previousPermit, [
    "previousPermitDeadline", "transaction",
  ], "previous Router permit observation");
  const previousPermitDeadline = raw.previousPermit.previousPermitDeadline === null
    ? null
    : decimalString(raw.previousPermit.previousPermitDeadline, "previous permit deadline");
  let transaction: RouterPreviousPermitObservationV1["transaction"] = null;
  if (raw.previousPermit.transaction !== null) {
    assertExactKeys(raw.previousPermit.transaction, [
      "blockHash", "blockNumber", "disposition", "transactionHash",
    ], "previous Router transaction observation");
    const disposition = raw.previousPermit.transaction.disposition;
    if (
      disposition !== "absent-after-finalized-deadline"
      && disposition !== "finalized-reverted"
    ) throw new TypeError("previous Router transaction disposition is invalid");
    const blockNumber = raw.previousPermit.transaction.blockNumber === null
      ? null
      : rpcQuantity(raw.previousPermit.transaction.blockNumber, "previous receipt block number");
    const blockHash = raw.previousPermit.transaction.blockHash === null
      ? null
      : bytes32(raw.previousPermit.transaction.blockHash, "previous receipt block hash");
    if (
      previousPermitDeadline === null
      || (disposition === "absent-after-finalized-deadline"
        && (blockNumber !== null || blockHash !== null))
      || (disposition === "finalized-reverted"
        && (blockNumber === null || blockHash === null))
    ) throw new TypeError("previous Router transaction observation is incomplete");
    transaction = deepFreeze({
      transactionHash: bytes32(
        raw.previousPermit.transaction.transactionHash,
        "previous transaction hash",
      ),
      disposition,
      blockNumber,
      blockHash,
    });
  }
  if (previousPermitDeadline === null && transaction !== null) {
    throw new TypeError("initial Router preflight unexpectedly has a previous transaction");
  }
  const core = {
    schemaVersion: "programmable.router-launch-unconsumed-evidence.v1" as const,
    chainId: "1" as const,
    router: BINDING.router.address,
    routerRuntimeKeccak256: BINDING.router.runtimeKeccak256,
    graphFactory: BINDING.graphFactory.address,
    graphFactoryRuntimeKeccak256: BINDING.graphFactory.runtimeKeccak256,
    launchId: bytes32(raw.launchId, "unconsumed launch id"),
    token: rpcAddress(raw.token, "unconsumed launch token"),
    poolId: bytes32(raw.poolId, "unconsumed pool id"),
    routeNonce: bytes32(raw.routeNonce, "unconsumed route nonce"),
    graphAuthorizationKey: bytes32(
      raw.graphAuthorizationKey,
      "unconsumed Graph authorization key",
    ),
    targetAccounts,
    componentAccounts,
    commonFinalizedAnchorHash: sha256(raw.commonFinalizedAnchorHash, "unconsumed anchor hash"),
    runtimeBindings: "matched-finalized-and-latest" as const,
    targetRuntimeState: "empty-finalized-and-latest" as const,
    graphAuthorizationState: "unconsumed-finalized-and-latest" as const,
    launchStampState: "empty-finalized-and-latest" as const,
    tokenIndexState: "empty-finalized-and-latest" as const,
    poolIndexState: "empty-finalized-and-latest" as const,
    componentIndexState: "empty-finalized-and-latest" as const,
    componentProofState: "empty-finalized-and-latest" as const,
    previousPermit: { previousPermitDeadline, transaction },
  };
  const evidence = deepFreeze({
    ...core,
    evidenceHash: canonicalSha256(core.schemaVersion, core),
  });
  if (raw.evidenceHash !== evidence.evidenceHash) {
    throw new TypeError("Router launch unconsumed evidence hash is invalid");
  }
  if (launch !== undefined && (
    evidence.launchId !== launch.plan.stampRequest.launchId
    || evidence.token !== launch.plan.stampRequest.token
    || evidence.poolId !== launch.poolId
    || evidence.routeNonce !== launch.plan.route.routeNonce
    || evidence.graphAuthorizationKey !== graphAuthorizationKeyV1(launch)
    || canonicalizeJson(evidence.targetAccounts)
      !== canonicalizeJson(launch.plan.route.expectedOutputs.map(({ account }) => account))
    || canonicalizeJson(evidence.componentAccounts)
      !== canonicalizeJson(launch.plan.stampRequest.components.map(({ account }) => account))
  )) throw new TypeError("Router launch unconsumed evidence does not match the compiled launch");
  return evidence;
}

export function graphAuthorizationKeyV1(
  launch: Readonly<CanonicalCustomGraphLaunchV1>,
): EvmBytes32V1 {
  const encoded = joinHex(
    BINDING.graphFactory.graphAuthorizationKeyTypeHash,
    quantityWord(1n),
    addressWord(BINDING.graphFactory.address),
    word(launch.plan.route.routeNamespace),
    word(launch.plan.route.routeNonce),
    addressWord(BINDING.router.address),
  );
  return keccak256(Buffer.from(encoded.slice(2), "hex")) as EvmBytes32V1;
}

function rpcBlock(value: unknown, label: string): Readonly<{
  number: EvmHexV1;
  hash: EvmBytes32V1;
  timestamp: EvmHexV1;
}> {
  if (value === null || typeof value !== "object" || Array.isArray(value)) {
    throw new TypeError(`${label} is unavailable`);
  }
  const block = value as Record<string, unknown>;
  return Object.freeze({
    number: rpcQuantity(block.number, `${label} number`),
    hash: bytes32(block.hash, `${label} hash`),
    timestamp: rpcQuantity(block.timestamp, `${label} timestamp`),
  });
}

function rpcObject(value: unknown, label: string): Record<string, unknown> {
  if (value === null || typeof value !== "object" || Array.isArray(value)) {
    throw new TypeError(`${label} is unavailable or invalid`);
  }
  return value as Record<string, unknown>;
}

function assertExactKeys(
  value: unknown,
  expected: readonly string[],
  label: string,
): asserts value is Record<string, unknown> {
  if (value === null || typeof value !== "object" || Array.isArray(value)) {
    throw new TypeError(`${label} is not an object`);
  }
  const actual = Reflect.ownKeys(value);
  const strings = actual.filter((key): key is string => typeof key === "string").sort();
  const wanted = [...expected].sort();
  if (
    actual.length !== strings.length
    || strings.length !== wanted.length
    || strings.some((key, index) => key !== wanted[index])
  ) throw new TypeError(`${label} has unexpected fields`);
}

function decimalString(value: unknown, label: string): string {
  if (typeof value !== "string" || !/^(?:0|[1-9][0-9]*)$/u.test(value)) {
    throw new TypeError(`${label} is invalid`);
  }
  return value;
}

function decodeAddressArray(value: EvmHexV1, label: string): readonly EvmAddressV1[] {
  const bytes = Buffer.from(value.slice(2), "hex");
  if (bytes.byteLength < 64 || bytes.byteLength % 32 !== 0 || readWord(bytes, 0) !== 32n) {
    throw new TypeError(`${label} ABI is invalid`);
  }
  const length = readSafeLength(bytes, 32, label);
  if (bytes.byteLength !== 64 + length * 32) throw new TypeError(`${label} ABI length is invalid`);
  const owners: EvmAddressV1[] = [];
  for (let index = 0; index < length; index += 1) {
    const item = bytes.subarray(64 + index * 32, 96 + index * 32);
    if (!item.subarray(0, 12).every((byte) => byte === 0)) throw new TypeError(`${label} address is invalid`);
    owners.push(`0x${item.subarray(12).toString("hex")}` as EvmAddressV1);
  }
  return Object.freeze(owners);
}

function decodeAbiString(value: EvmHexV1, label: string): string {
  const bytes = Buffer.from(value.slice(2), "hex");
  if (bytes.byteLength < 64 || bytes.byteLength % 32 !== 0 || readWord(bytes, 0) !== 32n) {
    throw new TypeError(`${label} ABI is invalid`);
  }
  const length = readSafeLength(bytes, 32, label);
  const padded = Math.ceil(length / 32) * 32;
  if (bytes.byteLength !== 64 + padded) throw new TypeError(`${label} ABI length is invalid`);
  if (!bytes.subarray(64 + length).every((byte) => byte === 0)) {
    throw new TypeError(`${label} ABI padding is nonzero`);
  }
  const text = bytes.subarray(64, 64 + length).toString("utf8");
  if (Buffer.from(text, "utf8").compare(bytes.subarray(64, 64 + length)) !== 0) {
    throw new TypeError(`${label} is not canonical UTF-8`);
  }
  return text;
}

function readSafeLength(bytes: Buffer, offset: number, label: string): number {
  const value = readWord(bytes, offset);
  if (value > BigInt(Number.MAX_SAFE_INTEGER)) throw new TypeError(`${label} ABI length is too large`);
  return Number(value);
}

function readWord(bytes: Buffer, offset: number): bigint {
  const word = bytes.subarray(offset, offset + 32);
  if (word.byteLength !== 32) throw new TypeError("ABI word is truncated");
  return BigInt(`0x${word.toString("hex")}`);
}

function addressWord(value: EvmAddressV1): EvmHexV1 {
  if (!/^0x[0-9a-f]{40}$/u.test(value)) throw new TypeError("address ABI word is invalid");
  return `0x${"0".repeat(24)}${value.slice(2)}`;
}

function word(value: EvmHexV1): EvmHexV1 {
  if (!/^0x[0-9a-f]{64}$/u.test(value)) throw new TypeError("ABI word is invalid");
  return value;
}

function quantityWord(value: bigint): EvmHexV1 {
  if (value < 0n || value >= 1n << 256n) throw new TypeError("ABI uint256 is invalid");
  return `0x${value.toString(16).padStart(64, "0")}`;
}

function joinHex(first: EvmHexV1, ...rest: readonly EvmHexV1[]): EvmHexV1 {
  return `0x${[first, ...rest].map((value) => value.slice(2)).join("")}`;
}

function flipDigestBit(value: EvmBytes32V1): EvmBytes32V1 {
  const bytes = Buffer.from(value.slice(2), "hex");
  bytes[31] = bytes[31]! ^ 1;
  return `0x${bytes.toString("hex")}`;
}

function bytes32(value: unknown, label: string): EvmBytes32V1 {
  if (typeof value !== "string" || !/^0x[0-9a-f]{64}$/u.test(value)) {
    throw new TypeError(`${label} is invalid`);
  }
  return value as EvmBytes32V1;
}

function rpcAddress(value: unknown, label: string): EvmAddressV1 {
  if (typeof value !== "string" || !/^0x[0-9a-f]{40}$/u.test(value) || BigInt(value) === 0n) {
    throw new TypeError(`${label} is invalid`);
  }
  return value as EvmAddressV1;
}

function sha256(value: unknown, label: string): Sha256Digest {
  if (typeof value !== "string" || !/^sha256:[0-9a-f]{64}$/u.test(value)) {
    throw new TypeError(`${label} is invalid`);
  }
  return value as Sha256Digest;
}

function hex(value: unknown, label: string): EvmHexV1 {
  if (typeof value !== "string" || !/^0x(?:[0-9a-f]{2})*$/u.test(value)) {
    throw new TypeError(`${label} is invalid`);
  }
  return value as EvmHexV1;
}

function rpcQuantity(value: unknown, label: string): EvmHexV1 {
  if (typeof value !== "string" || !/^0x(?:0|[1-9a-f][0-9a-f]*)$/u.test(value)) {
    throw new TypeError(`${label} is not a canonical JSON-RPC quantity`);
  }
  return value as EvmHexV1;
}

function quantity(value: bigint): EvmHexV1 {
  if (value < 0n) throw new TypeError("JSON-RPC quantity is negative");
  return `0x${value.toString(16)}`;
}

function boundedId(value: string, label: string): void {
  if (value.length === 0 || value.length > 256 || /[\u0000-\u001f\u007f]/u.test(value)) {
    throw new TypeError(`${label} is invalid`);
  }
}

function deepFreeze<T>(value: T): T {
  if (value !== null && typeof value === "object" && !Object.isFrozen(value)) {
    for (const nested of Object.values(value as Record<string, unknown>)) deepFreeze(nested);
    Object.freeze(value);
  }
  return value;
}
