import { canonicalSha256 } from "../../domain/hashing.js";
import type { Sha256Digest } from "../../domain/types.js";
import { keccak256V1 as keccak256 } from "./keccak.js";
import {
  PRODUCTION_ROUTER_SELF_SERVICE_BINDING_V1 as BINDING,
  type EvmAddressV1,
  type EvmBytes32V1,
  type EvmHexV1,
} from "./production-binding.js";
import type { RouterFinalityReadAuthorityV1 } from "./rpc.js";
import type { PreparedGitHubRouterLaunchV1 } from "./self-service.js";

export interface FinalizedRouterStampProofV1 {
  readonly schemaVersion: "programmable.finalized-router-stamp-proof.v2";
  readonly transactionHash: EvmBytes32V1;
  /** Actual wallet-assigned transaction nonce, not an authorization input. */
  readonly transactionNonce: EvmHexV1;
  /** Earlier pending-count observation retained only for diagnostics. */
  readonly pendingNonceAtPreparation: string | null;
  readonly blockNumber: EvmHexV1;
  readonly blockHash: EvmBytes32V1;
  readonly blockTimestamp: EvmHexV1;
  readonly launchId: EvmBytes32V1;
  readonly token: EvmAddressV1;
  readonly hook: EvmAddressV1;
  readonly poolId: EvmBytes32V1;
  readonly stampHash: EvmBytes32V1;
  readonly permitDigest: EvmBytes32V1;
  readonly componentProofs: readonly Readonly<{
    account: EvmAddressV1;
    runtimeCodeHash: EvmBytes32V1;
    kind: number;
    stampProof: EvmHexV1;
  }>[];
  readonly eventCount: number;
  readonly preparationHash: Sha256Digest;
  readonly proofHash: Sha256Digest;
}

export interface FailedRouterLaunchTransactionEvidenceV1 {
  readonly schemaVersion: "programmable.failed-router-launch-transaction-evidence.v1";
  readonly transactionHash: EvmBytes32V1;
  readonly transactionNonce: EvmHexV1;
  readonly blockNumber: EvmHexV1;
  readonly blockHash: EvmBytes32V1;
  readonly blockTimestamp: EvmHexV1;
  readonly preparationHash: Sha256Digest;
  readonly evidenceHash: Sha256Digest;
}

export class RouterLaunchTransactionRevertedError extends TypeError {
  readonly evidence: Readonly<FailedRouterLaunchTransactionEvidenceV1>;

  constructor(evidence: Readonly<FailedRouterLaunchTransactionEvidenceV1>) {
    super("finalized Router launch transaction reverted");
    this.name = "RouterLaunchTransactionRevertedError";
    this.evidence = evidence;
  }
}

export class RouterLaunchFinalityVerifierV1 {
  readonly #rpc: RouterFinalityReadAuthorityV1;

  constructor(input: Readonly<{
    rpc: RouterFinalityReadAuthorityV1;
  }>) {
    this.#rpc = input.rpc;
    Object.freeze(this);
  }

  async finalize(input: Readonly<{
    prepared: Readonly<PreparedGitHubRouterLaunchV1>;
    transactionHash: EvmBytes32V1;
  }>): Promise<Readonly<FinalizedRouterStampProofV1>> {
    assertPreparedHash(input.prepared);
    const transactionHash = bytes32(input.transactionHash, "launch transaction hash");
    const [transactionValue, receiptValue, finalizedAnchor] = await Promise.all([
      this.#rpc.readConsensus("eth_getTransactionByHash", [transactionHash]),
      this.#rpc.readConsensus("eth_getTransactionReceipt", [transactionHash]),
      this.#rpc.collectCommonFinalizedAnchor(),
    ]);
    const transaction = rpcObject(transactionValue, "launch transaction");
    const receipt = rpcObject(receiptValue, "launch receipt");
    const blockNumber = rpcQuantity(receipt.blockNumber, "receipt block number");
    const blockHash = bytes32(receipt.blockHash, "receipt block hash");
    const transactionNonce = rpcQuantity(transaction.nonce, "transaction nonce");
    if (BigInt(blockNumber) > BigInt(finalizedAnchor.blockNumber)) {
      throw new TypeError("launch transaction is not finalized by both RPC providers");
    }
    if (
      bytes32(transaction.hash, "observed transaction hash") !== transactionHash
      || bytes32(receipt.transactionHash, "receipt transaction hash") !== transactionHash
      || bytes32(transaction.blockHash, "transaction block hash") !== blockHash
      || rpcQuantity(transaction.blockNumber, "transaction block number") !== blockNumber
      || address(transaction.from, "transaction sender") !== input.prepared.launchWallet
      || address(transaction.to, "transaction target") !== BINDING.router.address
      || hex(transaction.input, "transaction input") !== input.prepared.calldata
      || BigInt(rpcQuantity(transaction.value, "transaction value")) !== BigInt(input.prepared.permit.value)
    ) throw new TypeError("finalized transaction does not match the exact browser action");
    const receiptStatus = rpcQuantity(receipt.status, "receipt status");
    if (
      (receiptStatus !== "0x0" && receiptStatus !== "0x1")
      || address(receipt.from, "receipt sender") !== input.prepared.launchWallet
      || address(receipt.to, "receipt target") !== BINDING.router.address
      || receipt.contractAddress !== null
    ) throw new TypeError("launch receipt is reverted or bound to another transaction");

    const blockTimestamp = await this.#proveCanonicalFinalizedReceiptBlock({
      receiptBlockNumber: blockNumber,
      receiptBlockHash: blockHash,
      finalizedBlockNumber: finalizedAnchor.blockNumber,
    });
    if (receiptStatus === "0x0") {
      const failedCore = {
        schemaVersion: "programmable.failed-router-launch-transaction-evidence.v1" as const,
        transactionHash,
        transactionNonce,
        blockNumber,
        blockHash,
        blockTimestamp,
        preparationHash: input.prepared.preparationHash,
      };
      throw new RouterLaunchTransactionRevertedError(deepFreeze({
        ...failedCore,
        evidenceHash: canonicalSha256(failedCore.schemaVersion, failedCore),
      }));
    }
    const logs = rpcArray(receipt.logs, "receipt logs").map((value, index) =>
      rpcLog(value, transactionHash, blockHash, index));
    const routerLogs = logs.filter(({ address }) => address === BINDING.router.address);
    assertExactRouterEvents(input.prepared, routerLogs);

    const tag = finalizedAnchor.blockNumber;
    await this.#verifyLaunchStampReadbacks(input.prepared, tag);
    const componentProofs = [];
    for (const component of input.prepared.expectedComponents) {
      const proof = await this.#rpc.ethCallConsensus({
        to: BINDING.router.address,
        data: joinHex(BINDING.selectors.stampProof, addressWord(component.account)),
      }, tag);
      const expectedProof = joinHex(input.prepared.expectedLaunchId, input.prepared.expectedStampHash);
      if (proof !== expectedProof) throw new TypeError("finalized component stampProof readback is invalid");
      const recordedRuntime = await this.#rpc.ethCallConsensus({
        to: BINDING.router.address,
        data: joinHex(BINDING.selectors.componentRuntimeCodeHash, addressWord(component.account)),
      }, tag);
      if (recordedRuntime !== component.runtimeCodeHash) {
        throw new TypeError("finalized component runtime-hash mapping is invalid");
      }
      const runtime = hex(await this.#rpc.readConsensus("eth_getCode", [component.account, tag]),
        "finalized component runtime");
      if (runtime === "0x" || keccak256(Buffer.from(runtime.slice(2), "hex")) !== component.runtimeCodeHash) {
        throw new TypeError("finalized component runtime no longer matches its stamp");
      }
      componentProofs.push({ ...component, stampProof: proof });
    }
    const proofCore = {
      schemaVersion: "programmable.finalized-router-stamp-proof.v2" as const,
      transactionHash,
      transactionNonce,
      pendingNonceAtPreparation: input.prepared.browserAction.pendingNonceAtPreparation,
      blockNumber,
      blockHash,
      blockTimestamp,
      launchId: input.prepared.expectedLaunchId,
      token: input.prepared.expectedComponents.find(({ kind }) => kind === 1)!.account,
      hook: input.prepared.expectedComponents.find(({ kind }) => kind === 2)!.account,
      poolId: input.prepared.expectedPoolId,
      stampHash: input.prepared.expectedStampHash,
      permitDigest: input.prepared.permitDigest,
      componentProofs,
      eventCount: routerLogs.length,
      preparationHash: input.prepared.preparationHash,
    };
    const proof = deepFreeze({
      ...proofCore,
      proofHash: canonicalSha256("programmable.finalized-router-stamp-proof.v2", proofCore),
    });
    return proof;
  }

  async #proveCanonicalFinalizedReceiptBlock(input: Readonly<{
    receiptBlockNumber: EvmHexV1;
    receiptBlockHash: EvmBytes32V1;
    finalizedBlockNumber: EvmHexV1;
  }>): Promise<EvmHexV1> {
    if (BigInt(input.receiptBlockNumber) > BigInt(input.finalizedBlockNumber)) {
      throw new TypeError("receipt block is newer than the common finalized anchor");
    }
    // Both independent providers report the receipt height below their common
    // finalized height. Reading that historical height by number binds the
    // receipt to their canonical finalized chain without a permanent rolling
    // header window: recovery remains possible after arbitrarily long outages.
    const block = rpcObject(await this.#rpc.readConsensus(
      "eth_getBlockByNumber",
      [input.receiptBlockNumber, false],
    ), "canonical finalized receipt block");
    const timestamp = rpcQuantity(block.timestamp, "canonical receipt block timestamp");
    if (
      bytes32(block.hash, "canonical receipt block hash") !== input.receiptBlockHash
      || rpcQuantity(block.number, "canonical receipt block number") !== input.receiptBlockNumber
    ) throw new TypeError("receipt block is not canonical at the finalized height");
    return timestamp;
  }

  async #verifyLaunchStampReadbacks(
    prepared: Readonly<PreparedGitHubRouterLaunchV1>,
    tag: EvmHexV1,
  ): Promise<void> {
    const token = prepared.expectedComponents.find(({ kind }) => kind === 1)!.account;
    const hook = prepared.expectedComponents.find(({ kind }) => kind === 2)!.account;
    const launchStamp = await this.#rpc.ethCallConsensus({
      to: BINDING.router.address,
      data: joinHex(BINDING.selectors.launchStamp, prepared.expectedLaunchId),
    }, tag);
    const words = staticWords(launchStamp, 14, "launchStamp readback");
    const expected = [
      uintWord(1),
      addressWord(prepared.launchWallet),
      addressWord(token),
      addressWord(hook),
      addressWord(BINDING.poolManager.address),
      prepared.expectedPoolId,
      poolKeyHashFromPrepared(prepared),
      componentSetHashFromPrepared(prepared),
      prepared.permit.routePayloadHash,
      addressWord(BINDING.graphFactory.address),
      BINDING.graphFactory.runtimeKeccak256,
      prepared.permit.expectedResultHash,
      prepared.permitDigest,
      prepared.expectedStampHash,
    ];
    if (words.some((word, index) => word !== expected[index])) {
      throw new TypeError("finalized launchStamp record does not match the prepared launch");
    }
    const launchIdByToken = await this.#rpc.ethCallConsensus({
      to: BINDING.router.address,
      data: joinHex(BINDING.selectors.launchIdByToken, addressWord(token)),
    }, tag);
    const launchIdByPool = await this.#rpc.ethCallConsensus({
      to: BINDING.router.address,
      data: joinHex(
        BINDING.selectors.launchIdByPool,
        addressWord(BINDING.poolManager.address),
        prepared.expectedPoolId,
      ),
    }, tag);
    if (launchIdByToken !== prepared.expectedLaunchId || launchIdByPool !== prepared.expectedLaunchId) {
      throw new TypeError("finalized token/pool Router indices do not match the launch id");
    }
    for (const component of prepared.expectedComponents) {
      const launchId = await this.#rpc.ethCallConsensus({
        to: BINDING.router.address,
        data: joinHex(BINDING.selectors.launchIdByComponent, addressWord(component.account)),
      }, tag);
      if (launchId !== prepared.expectedLaunchId) {
        throw new TypeError("finalized component Router index does not match the launch id");
      }
    }
  }
}

export function assertFailedRouterLaunchTransactionEvidenceV1(
  raw: unknown,
  prepared: Readonly<PreparedGitHubRouterLaunchV1>,
): Readonly<FailedRouterLaunchTransactionEvidenceV1> {
  assertPreparedHash(prepared);
  const value = rpcObject(raw, "failed Router launch transaction evidence");
  const requiredKeys = [
    "blockHash", "blockNumber", "blockTimestamp", "evidenceHash", "preparationHash",
    "schemaVersion", "transactionHash", "transactionNonce",
  ].sort();
  const actualKeys = Object.keys(value).sort();
  if (
    actualKeys.length !== requiredKeys.length
    || actualKeys.some((key, index) => key !== requiredKeys[index])
    || value.schemaVersion !== "programmable.failed-router-launch-transaction-evidence.v1"
    || value.preparationHash !== prepared.preparationHash
  ) throw new TypeError("failed Router launch transaction evidence shape is invalid");
  const core = {
    schemaVersion: "programmable.failed-router-launch-transaction-evidence.v1" as const,
    transactionHash: bytes32(value.transactionHash, "failed transaction hash"),
    transactionNonce: rpcQuantity(value.transactionNonce, "failed transaction nonce"),
    blockNumber: rpcQuantity(value.blockNumber, "failed transaction block number"),
    blockHash: bytes32(value.blockHash, "failed transaction block hash"),
    blockTimestamp: rpcQuantity(value.blockTimestamp, "failed transaction block timestamp"),
    preparationHash: prepared.preparationHash,
  };
  const evidence = deepFreeze({
    ...core,
    evidenceHash: canonicalSha256(core.schemaVersion, core),
  });
  if (value.evidenceHash !== evidence.evidenceHash) {
    throw new TypeError("failed Router launch transaction evidence hash is invalid");
  }
  return evidence;
}

export function assertFinalizedRouterStampProofV1(
  raw: unknown,
  prepared: Readonly<PreparedGitHubRouterLaunchV1>,
): Readonly<FinalizedRouterStampProofV1> {
  assertPreparedHash(prepared);
  const value = rpcObject(raw, "finalized Router stamp proof");
  const requiredKeys = [
    "blockHash", "blockNumber", "blockTimestamp", "componentProofs", "eventCount",
    "hook", "launchId",
    "pendingNonceAtPreparation", "permitDigest", "poolId", "preparationHash",
    "proofHash", "schemaVersion", "stampHash", "token", "transactionHash",
    "transactionNonce",
  ].sort();
  const actualKeys = Object.keys(value).sort();
  if (
    actualKeys.length !== requiredKeys.length
    || actualKeys.some((key, index) => key !== requiredKeys[index])
    || value.schemaVersion !== "programmable.finalized-router-stamp-proof.v2"
  ) throw new TypeError("finalized Router stamp proof shape is invalid");
  const blockNumber = rpcQuantity(value.blockNumber, "proof block number");
  const token = prepared.expectedComponents.find(({ kind }) => kind === 1)?.account;
  const hook = prepared.expectedComponents.find(({ kind }) => kind === 2)?.account;
  if (
    token === undefined || hook === undefined
    || value.launchId !== prepared.expectedLaunchId
    || value.token !== token
    || value.hook !== hook
    || value.poolId !== prepared.expectedPoolId
    || value.stampHash !== prepared.expectedStampHash
    || value.permitDigest !== prepared.permitDigest
    || value.preparationHash !== prepared.preparationHash
    || value.pendingNonceAtPreparation !== prepared.browserAction.pendingNonceAtPreparation
    || value.eventCount !== 2 + prepared.expectedComponents.length
  ) throw new TypeError("finalized Router stamp proof does not match its preparation");
  bytes32(value.transactionHash, "proof transaction hash");
  rpcQuantity(value.transactionNonce, "proof transaction nonce");
  bytes32(value.blockHash, "proof block hash");
  rpcQuantity(value.blockTimestamp, "proof block timestamp");
  const components = rpcArray(value.componentProofs, "proof component set");
  if (components.length !== prepared.expectedComponents.length) {
    throw new TypeError("finalized Router stamp proof component count is invalid");
  }
  const expectedStampProof = joinHex(prepared.expectedLaunchId, prepared.expectedStampHash);
  components.forEach((rawComponent, index) => {
    const component = rpcObject(rawComponent, `proof component ${index}`);
    const keys = Object.keys(component).sort();
    const expectedKeys = ["account", "kind", "runtimeCodeHash", "stampProof"].sort();
    const expected = prepared.expectedComponents[index]!;
    if (
      keys.length !== expectedKeys.length
      || keys.some((key, keyIndex) => key !== expectedKeys[keyIndex])
      || component.account !== expected.account
      || component.runtimeCodeHash !== expected.runtimeCodeHash
      || component.kind !== expected.kind
      || component.stampProof !== expectedStampProof
    ) throw new TypeError(`finalized Router component proof ${index} is invalid`);
  });
  const { proofHash, ...proofCore } = value;
  if (
    typeof proofHash !== "string"
    || proofHash !== canonicalSha256("programmable.finalized-router-stamp-proof.v2", proofCore)
  ) throw new TypeError("finalized Router stamp proof hash is invalid");
  return deepFreeze(structuredClone(raw)) as Readonly<FinalizedRouterStampProofV1>;
}

interface ParsedRpcLog {
  readonly address: EvmAddressV1;
  readonly topics: readonly EvmBytes32V1[];
  readonly data: EvmHexV1;
}

function assertExactRouterEvents(
  prepared: Readonly<PreparedGitHubRouterLaunchV1>,
  logs: readonly ParsedRpcLog[],
): void {
  const token = prepared.expectedComponents.find(({ kind }) => kind === 1);
  const hook = prepared.expectedComponents.find(({ kind }) => kind === 2);
  if (token === undefined || hook === undefined || logs.length !== 2 + prepared.expectedComponents.length) {
    throw new TypeError("Router receipt does not contain the exact required event count");
  }
  const launchTopics = [
    BINDING.eventTopics.launchStamped,
    prepared.expectedLaunchId,
    addressWord(token.account),
    addressWord(hook.account),
  ];
  const launchData = joinHex(
    addressWord(BINDING.poolManager.address),
    prepared.expectedPoolId,
    prepared.expectedStampHash,
  );
  const routeTopics = [
    BINDING.eventTopics.routeStamped,
    prepared.expectedLaunchId,
    uintWord(1),
    prepared.permit.routePayloadHash,
  ];
  const routeData = joinHex(prepared.permit.expectedResultHash, prepared.permitDigest);
  const launchMatches = logs.filter((log) => sameWords(log.topics, launchTopics) && log.data === launchData);
  const routeMatches = logs.filter((log) => sameWords(log.topics, routeTopics) && log.data === routeData);
  if (launchMatches.length !== 1 || routeMatches.length !== 1) {
    throw new TypeError("Router launch/route stamp events are absent or ambiguous");
  }
  for (const component of prepared.expectedComponents) {
    const topics = [
      BINDING.eventTopics.componentStamped,
      prepared.expectedLaunchId,
      addressWord(component.account),
      uintWord(component.kind),
    ];
    const matches = logs.filter((log) =>
      sameWords(log.topics, topics) && log.data === component.runtimeCodeHash);
    if (matches.length !== 1) throw new TypeError("Router component stamp event is absent or ambiguous");
  }
}

function rpcLog(
  value: unknown,
  transactionHash: EvmBytes32V1,
  blockHash: EvmBytes32V1,
  index: number,
): Readonly<ParsedRpcLog> {
  const log = rpcObject(value, `receipt log ${index}`);
  if (
    bytes32(log.transactionHash, `receipt log ${index} transaction hash`) !== transactionHash
    || bytes32(log.blockHash, `receipt log ${index} block hash`) !== blockHash
    || log.removed !== false
  ) throw new TypeError(`receipt log ${index} is not canonical`);
  return Object.freeze({
    address: address(log.address, `receipt log ${index} address`),
    topics: Object.freeze(rpcArray(log.topics, `receipt log ${index} topics`).map((topic) =>
      bytes32(topic, `receipt log ${index} topic`))),
    data: hex(log.data, `receipt log ${index} data`),
  });
}

function assertPreparedHash(prepared: Readonly<PreparedGitHubRouterLaunchV1>): void {
  const { preparationHash, ...core } = prepared;
  if (preparationHash !== canonicalSha256("programmable.prepared-github-router-launch.v3", core)) {
    throw new TypeError("prepared Router launch hash is invalid");
  }
}

function poolKeyHashFromPrepared(prepared: Readonly<PreparedGitHubRouterLaunchV1>): EvmBytes32V1 {
  return prepared.poolKeyHash;
}

function componentSetHashFromPrepared(prepared: Readonly<PreparedGitHubRouterLaunchV1>): EvmBytes32V1 {
  return prepared.componentSetHash;
}

function staticWords(value: EvmHexV1, count: number, label: string): readonly EvmBytes32V1[] {
  const bytes = Buffer.from(value.slice(2), "hex");
  if (bytes.byteLength !== count * 32) throw new TypeError(`${label} has an invalid ABI length`);
  const words: EvmBytes32V1[] = [];
  for (let index = 0; index < count; index += 1) {
    words.push(`0x${bytes.subarray(index * 32, (index + 1) * 32).toString("hex")}`);
  }
  return Object.freeze(words);
}

function sameWords(left: readonly string[], right: readonly string[]): boolean {
  return left.length === right.length && left.every((word, index) => word === right[index]);
}

function addressWord(value: EvmAddressV1): EvmBytes32V1 {
  return `0x${"0".repeat(24)}${value.slice(2)}`;
}

function uintWord(value: number): EvmBytes32V1 {
  if (!Number.isSafeInteger(value) || value < 0) throw new TypeError("event uint word is invalid");
  return `0x${value.toString(16).padStart(64, "0")}`;
}

function joinHex(first: EvmHexV1, ...rest: readonly EvmHexV1[]): EvmHexV1 {
  return `0x${[first, ...rest].map((value) => value.slice(2)).join("")}`;
}

function rpcObject(value: unknown, label: string): Record<string, unknown> {
  if (value === null || typeof value !== "object" || Array.isArray(value)) {
    throw new TypeError(`${label} is unavailable or invalid`);
  }
  return value as Record<string, unknown>;
}

function rpcArray(value: unknown, label: string): readonly unknown[] {
  if (!Array.isArray(value)) throw new TypeError(`${label} is invalid`);
  return value;
}

function address(value: unknown, label: string): EvmAddressV1 {
  if (typeof value !== "string" || !/^0x[0-9a-fA-F]{40}$/u.test(value)) {
    throw new TypeError(`${label} is invalid`);
  }
  return value.toLowerCase() as EvmAddressV1;
}

function bytes32(value: unknown, label: string): EvmBytes32V1 {
  if (typeof value !== "string" || !/^0x[0-9a-fA-F]{64}$/u.test(value)) {
    throw new TypeError(`${label} is invalid`);
  }
  return value.toLowerCase() as EvmBytes32V1;
}

function hex(value: unknown, label: string): EvmHexV1 {
  if (typeof value !== "string" || !/^0x(?:[0-9a-fA-F]{2})*$/u.test(value)) {
    throw new TypeError(`${label} is invalid`);
  }
  return value.toLowerCase() as EvmHexV1;
}

function rpcQuantity(value: unknown, label: string): EvmHexV1 {
  if (typeof value !== "string" || !/^0x(?:0|[1-9a-f][0-9a-f]*)$/u.test(value)) {
    throw new TypeError(`${label} is invalid`);
  }
  return value as EvmHexV1;
}

function deepFreeze<T>(value: T): T {
  if (value !== null && typeof value === "object" && !Object.isFrozen(value)) {
    for (const nested of Object.values(value as Record<string, unknown>)) deepFreeze(nested);
    Object.freeze(value);
  }
  return value;
}
