import { createHash } from "node:crypto";

import {
  canonicalizeJson,
  parseStrictJson,
  type JsonValue,
} from "../../domain/canonical-json.js";
import { canonicalSha256 } from "../../domain/hashing.js";
import type { Sha256Digest } from "../../domain/types.js";
import { keccak256V1 as keccak256 } from "./keccak.js";
import type { EvmAddressV1 } from "./production-binding.js";

export const HOOKBUILDER_APPLICANT_REQUEST_MAXIMUM_BYTES_V1 = 65_536 as const;
export const HOOKBUILDER_APPLICANT_CANONICALIZATION_V1 =
  "urn:programmable:canonical-json:2.0.0" as const;

/**
 * Immutable public-main identity of the Hookbuilder Applicant 1.1 contract.
 * The JSON Schema is a structural gate. The pinned semantic core and this
 * Adapter's code-owned parser additionally enforce canonical SemVer, the
 * lowercase derived permission mask, and a nonzero recipient for nonzero fees.
 */
export const HOOKBUILDER_APPLICANT_1_1_PUBLIC_MAIN_BINDING_V1 = deepFreeze({
  schemaVersion: "programmable.hookbuilder-applicant-1.1-public-main-binding.v1" as const,
  repository: "https://github.com/0xprogrammable/hookbuilder" as const,
  commitSha: "d928f56218409f8511cec7ab43410b1bdfaa1450" as const,
  treeSha: "f62326ae214669ef67eb2d43ff5700d6a19503c2" as const,
  schemaPath: "submissions/schema/applicant-submission-v1.schema.json" as const,
  schemaSha256:
    "sha256:8d250114631d20f42e02ab195d80bd0123ff970cd07f7fd328b874b8abac87b5" as const,
  semanticCorePath: "scripts/applicant-submission-core.mjs" as const,
  semanticCoreSha256:
    "sha256:9bfcf57828929f8705b78b28eb0988ab7c2a966b6397829435916e94371d77c6" as const,
  examplePath: "submissions/examples/applicant-submission-v1.example.json" as const,
  exampleRawByteLength: 1_766 as const,
  exampleRawSha256:
    "sha256:b33e808a5d43164813890117f5cac28f1b193285f595865b38f50d3ef471f11e" as const,
  canonicalization: HOOKBUILDER_APPLICANT_CANONICALIZATION_V1,
  canonicalExampleByteLength: 1_438 as const,
  canonicalExampleSha256:
    "sha256:6575ab84fe93f388e96a7f042a7377859dfcd435e9c2810704e621b6a78a5794" as const,
  requestPathTemplate:
    "submissions/requests/<source.repositoryId>-<identifiers.hookId>.json" as const,
  requestedRoute: Object.freeze({
    routeId: "custom-graph" as const,
    routeVersion: "1.0.0" as const,
    chainId: "1" as const,
  }),
});

const PERMISSION_KEYS = Object.freeze([
  "beforeInitialize",
  "afterInitialize",
  "beforeAddLiquidity",
  "afterAddLiquidity",
  "beforeRemoveLiquidity",
  "afterRemoveLiquidity",
  "beforeSwap",
  "afterSwap",
  "beforeDonate",
  "afterDonate",
  "beforeSwapReturnDelta",
  "afterSwapReturnDelta",
  "afterAddLiquidityReturnDelta",
  "afterRemoveLiquidityReturnDelta",
] as const);
const PERMISSION_BITS = Object.freeze(Object.fromEntries(
  PERMISSION_KEYS.map((key, index) => [key, 1 << (PERMISSION_KEYS.length - 1 - index)]),
) as Readonly<Record<(typeof PERMISSION_KEYS)[number], number>>);

export interface HookbuilderApplicantSubmissionV1 {
  readonly $schema: "urn:programmable:applicant-submission:1.1.0";
  readonly schemaVersion: "1.1.0";
  readonly intake: Readonly<{
    repository: "0xprogrammable/hookbuilder";
    repositoryId: 1320085947;
  }>;
  readonly applicant: Readonly<{
    githubLogin: string;
    /** Exact EIP-55 form in the public request; normalized before Router use. */
    launchWallet: string;
  }>;
  readonly source: Readonly<{
    repository: string;
    repositoryId: number;
    commit: string;
    tree: string;
  }>;
  readonly identifiers: Readonly<{
    hookId: string;
    hookVersion: string;
    templateId: string;
    templateVersion: string;
    modelId: string;
    modelVersion: string;
  }>;
  readonly hook: Readonly<{
    addressFlagMask: string;
    permissions: Readonly<Record<(typeof PERMISSION_KEYS)[number], boolean>>;
  }>;
  readonly fee: Readonly<{
    amountPips: number;
    denominator: 1_000_000;
    currencyBasis: "input" | "output" | "quote" | "none";
    recipient: string | null;
    mutable: boolean;
  }>;
  readonly requestedRoute: Readonly<{
    routeId: "custom-graph";
    routeVersion: "1.0.0";
    chainId: "1";
  }>;
  readonly requestedActions: readonly ["review"];
  readonly notes: string | null;
}

export interface HookbuilderApplicantRequestEvidenceV1 {
  readonly schemaVersion: "programmable.hookbuilder-applicant-request-evidence.v1";
  readonly requestPath: string;
  readonly rawJsonUtf8: string;
  readonly rawByteLength: number;
  readonly rawSha256: Sha256Digest;
  readonly canonicalization: typeof HOOKBUILDER_APPLICANT_CANONICALIZATION_V1;
  readonly canonicalJsonUtf8: string;
  readonly canonicalByteLength: number;
  readonly canonicalSha256: Sha256Digest;
  readonly evidenceHash: Sha256Digest;
}

export function createHookbuilderApplicantRequestEvidenceV1(input: Readonly<{
  requestPath: string;
  rawJsonUtf8: string;
  canonicalJsonUtf8: string;
}>): Readonly<{
  evidence: Readonly<HookbuilderApplicantRequestEvidenceV1>;
  request: Readonly<HookbuilderApplicantSubmissionV1>;
  launchWallet: EvmAddressV1;
}> {
  const raw = strictRequest(input.rawJsonUtf8, "raw Hookbuilder Applicant request");
  const canonical = strictRequest(
    input.canonicalJsonUtf8,
    "canonical Hookbuilder Applicant request",
  );
  if (
    canonicalizeJson(raw) !== input.canonicalJsonUtf8
    || canonicalizeJson(canonical) !== input.canonicalJsonUtf8
  ) {
    throw new TypeError("Hookbuilder Applicant canonical bytes do not match the raw request semantics");
  }
  const request = assertHookbuilderApplicantSubmissionV1(canonical);
  const expectedPath = hookbuilderApplicantRequestPathV1({
    sourceRepositoryId: String(request.source.repositoryId),
    hookId: request.identifiers.hookId,
  });
  if (input.requestPath !== expectedPath) {
    throw new TypeError("Hookbuilder Applicant request path is not deterministic");
  }
  const rawByteLength = Buffer.byteLength(input.rawJsonUtf8, "utf8");
  const canonicalByteLength = Buffer.byteLength(input.canonicalJsonUtf8, "utf8");
  const core = {
    schemaVersion: "programmable.hookbuilder-applicant-request-evidence.v1" as const,
    requestPath: expectedPath,
    rawJsonUtf8: input.rawJsonUtf8,
    rawByteLength,
    rawSha256: rawSha256(input.rawJsonUtf8),
    canonicalization: HOOKBUILDER_APPLICANT_CANONICALIZATION_V1,
    canonicalJsonUtf8: input.canonicalJsonUtf8,
    canonicalByteLength,
    canonicalSha256: rawSha256(input.canonicalJsonUtf8),
  };
  return deepFreeze({
    evidence: {
      ...core,
      evidenceHash: canonicalSha256(core.schemaVersion, core),
    },
    request,
    launchWallet: normalizeEip55Address(request.applicant.launchWallet, "Applicant launch wallet"),
  });
}

export function assertHookbuilderApplicantRequestEvidenceV1(
  raw: unknown,
): Readonly<{
  evidence: Readonly<HookbuilderApplicantRequestEvidenceV1>;
  request: Readonly<HookbuilderApplicantSubmissionV1>;
  launchWallet: EvmAddressV1;
}> {
  assertExactKeys(raw, [
    "canonicalByteLength", "canonicalJsonUtf8", "canonicalSha256", "canonicalization",
    "evidenceHash", "rawByteLength", "rawJsonUtf8", "rawSha256", "requestPath",
    "schemaVersion",
  ], "Hookbuilder Applicant request evidence");
  if (raw.schemaVersion !== "programmable.hookbuilder-applicant-request-evidence.v1") {
    throw new TypeError("Hookbuilder Applicant request evidence schema is invalid");
  }
  const rebuilt = createHookbuilderApplicantRequestEvidenceV1({
    requestPath: raw.requestPath as string,
    rawJsonUtf8: raw.rawJsonUtf8 as string,
    canonicalJsonUtf8: raw.canonicalJsonUtf8 as string,
  });
  if (canonicalizeJson(raw) !== canonicalizeJson(rebuilt.evidence)) {
    throw new TypeError("Hookbuilder Applicant request evidence is invalid");
  }
  return rebuilt;
}

export function hookbuilderApplicantRequestPathV1(input: Readonly<{
  sourceRepositoryId: string;
  hookId: string;
}>): string {
  if (!/^[1-9][0-9]{0,15}$/u.test(input.sourceRepositoryId)) {
    throw new TypeError("Hookbuilder Applicant source repository id is invalid");
  }
  const hookId = id(input.hookId, "Hookbuilder Applicant hook id");
  return `submissions/requests/${input.sourceRepositoryId}-${hookId}.json`;
}

export function assertHookbuilderApplicantSubmissionV1(
  raw: JsonValue,
): Readonly<HookbuilderApplicantSubmissionV1> {
  assertExactKeys(raw, [
    "$schema", "applicant", "fee", "hook", "identifiers", "intake", "notes",
    "requestedActions", "requestedRoute", "schemaVersion", "source",
  ], "Hookbuilder Applicant request");
  if (
    raw.$schema !== "urn:programmable:applicant-submission:1.1.0"
    || raw.schemaVersion !== "1.1.0"
  ) throw new TypeError("Hookbuilder Applicant request schema is invalid");

  assertExactKeys(raw.intake, ["repository", "repositoryId"], "Hookbuilder intake");
  if (
    raw.intake.repository !== "0xprogrammable/hookbuilder"
    || raw.intake.repositoryId !== 1_320_085_947
  ) throw new TypeError("Hookbuilder Applicant intake binding is invalid");

  assertExactKeys(raw.applicant, ["githubLogin", "launchWallet"], "Hookbuilder applicant");
  const githubLogin = githubLoginValue(raw.applicant.githubLogin);
  const launchWallet = eip55Address(raw.applicant.launchWallet, "Applicant launch wallet");

  assertExactKeys(raw.source, ["commit", "repository", "repositoryId", "tree"], "Applicant source");
  const sourceRepositoryId = positiveSafeInteger(raw.source.repositoryId, "source repository id");
  const sourceRepository = repositoryUrl(raw.source.repository);
  const sourceCommit = gitSha(raw.source.commit, "source commit");
  const sourceTree = gitSha(raw.source.tree, "source tree");

  assertExactKeys(raw.identifiers, [
    "hookId", "hookVersion", "modelId", "modelVersion", "templateId", "templateVersion",
  ], "Applicant identifiers");
  const identifiers = {
    hookId: id(raw.identifiers.hookId, "hook id"),
    hookVersion: semver(raw.identifiers.hookVersion, "hook version"),
    templateId: id(raw.identifiers.templateId, "template id"),
    templateVersion: semver(raw.identifiers.templateVersion, "template version"),
    modelId: id(raw.identifiers.modelId, "model id"),
    modelVersion: semver(raw.identifiers.modelVersion, "model version"),
  };

  assertExactKeys(raw.hook, ["addressFlagMask", "permissions"], "Applicant hook");
  if (typeof raw.hook.addressFlagMask !== "string" || !/^0x[0-3][0-9a-fA-F]{3}$/u.test(raw.hook.addressFlagMask)) {
    throw new TypeError("Applicant hook address flag mask is invalid");
  }
  assertExactKeys(raw.hook.permissions, PERMISSION_KEYS, "Applicant hook permissions");
  const rawPermissions = raw.hook.permissions;
  const permissions = Object.fromEntries(PERMISSION_KEYS.map((key) => {
    const value = rawPermissions[key];
    if (typeof value !== "boolean") throw new TypeError(`Applicant hook permission ${key} is invalid`);
    return [key, value];
  })) as Record<(typeof PERMISSION_KEYS)[number], boolean>;
  const expectedAddressFlagMask = `0x${PERMISSION_KEYS.reduce(
    (mask, key) => permissions[key] ? mask | PERMISSION_BITS[key] : mask,
    0,
  ).toString(16).padStart(4, "0")}`;
  if (raw.hook.addressFlagMask !== expectedAddressFlagMask) {
    throw new TypeError("Applicant hook address flag mask does not match its 14 permissions");
  }

  assertExactKeys(raw.fee, [
    "amountPips", "currencyBasis", "denominator", "mutable", "recipient",
  ], "Applicant fee");
  const amountPips = nonnegativeSafeInteger(raw.fee.amountPips, "fee amount pips");
  if (amountPips > 1_000_000 || raw.fee.denominator !== 1_000_000) {
    throw new TypeError("Applicant fee denominator or amount is invalid");
  }
  if (!["input", "output", "quote", "none"].includes(raw.fee.currencyBasis as string)) {
    throw new TypeError("Applicant fee currency basis is invalid");
  }
  if (typeof raw.fee.mutable !== "boolean") throw new TypeError("Applicant fee mutability is invalid");
  const feeRecipient = raw.fee.recipient === null
    ? null
    : evmAddress(raw.fee.recipient, "fee recipient", false);
  if (
    (amountPips === 0 && (raw.fee.currencyBasis !== "none" || feeRecipient !== null))
    || (amountPips > 0 && (raw.fee.currencyBasis === "none" || feeRecipient === null))
  ) throw new TypeError("Applicant fee amount, basis, and recipient are inconsistent");

  assertExactKeys(raw.requestedRoute, [
    "chainId", "routeId", "routeVersion",
  ], "Applicant requested route");
  const routeId = id(raw.requestedRoute.routeId, "route id");
  const routeVersion = semver(raw.requestedRoute.routeVersion, "route version");
  if (typeof raw.requestedRoute.chainId !== "string" || !/^[1-9][0-9]{0,77}$/u.test(raw.requestedRoute.chainId)) {
    throw new TypeError("Applicant requested chain id is invalid");
  }
  if (
    !Array.isArray(raw.requestedActions)
    || raw.requestedActions.length !== 1
    || raw.requestedActions[0] !== "review"
  ) throw new TypeError("Applicant requested actions are invalid");
  if (routeId !== "custom-graph" || routeVersion !== "1.0.0" || raw.requestedRoute.chainId !== "1") {
    throw new TypeError("Applicant requested route is not supported by the manual Router beta");
  }
  if (raw.notes !== null && (typeof raw.notes !== "string" || [...raw.notes].length > 1_000)) {
    throw new TypeError("Applicant notes are invalid");
  }

  return deepFreeze({
    $schema: raw.$schema,
    schemaVersion: raw.schemaVersion,
    intake: {
      repository: raw.intake.repository,
      repositoryId: raw.intake.repositoryId,
    },
    applicant: { githubLogin, launchWallet },
    source: {
      repository: sourceRepository,
      repositoryId: sourceRepositoryId,
      commit: sourceCommit,
      tree: sourceTree,
    },
    identifiers,
    hook: { addressFlagMask: raw.hook.addressFlagMask, permissions },
    fee: {
      amountPips,
      denominator: 1_000_000,
      currencyBasis: raw.fee.currencyBasis as "input" | "output" | "quote" | "none",
      recipient: feeRecipient === null ? null : raw.fee.recipient as string,
      mutable: raw.fee.mutable,
    },
    requestedRoute: {
      routeId: "custom-graph",
      routeVersion: "1.0.0",
      chainId: "1",
    },
    requestedActions: ["review"],
    notes: raw.notes,
  });
}

function strictRequest(value: unknown, label: string): JsonValue {
  if (typeof value !== "string") throw new TypeError(`${label} is not a string`);
  try {
    return parseStrictJson(value, {
      maximumBytes: HOOKBUILDER_APPLICANT_REQUEST_MAXIMUM_BYTES_V1,
      maximumDepth: 32,
    });
  } catch (error) {
    throw new TypeError(`${label} is invalid`, { cause: error });
  }
}

function rawSha256(value: string): Sha256Digest {
  return `sha256:${createHash("sha256").update(value, "utf8").digest("hex")}`;
}

function githubLoginValue(value: unknown): string {
  if (typeof value !== "string" || !/^[A-Za-z0-9](?:[A-Za-z0-9-]{0,37}[A-Za-z0-9])?$/u.test(value)) {
    throw new TypeError("Applicant GitHub login is invalid");
  }
  return value;
}

function id(value: unknown, label: string): string {
  if (typeof value !== "string" || value.length > 80 || !/^[a-z0-9]+(?:-[a-z0-9]+)*$/u.test(value)) {
    throw new TypeError(`${label} is invalid`);
  }
  return value;
}

function semver(value: unknown, label: string): string {
  if (
    typeof value !== "string"
    || value.length > 100
    || !/^(?:0|[1-9][0-9]*)\.(?:0|[1-9][0-9]*)\.(?:0|[1-9][0-9]*)$/u.test(value)
  ) {
    throw new TypeError(`${label} is invalid`);
  }
  return value;
}

function repositoryUrl(value: unknown): string {
  if (
    typeof value !== "string"
    || value.length > 200
    || !/^https:\/\/github\.com\/(?![^/]*--)[A-Za-z0-9](?:[A-Za-z0-9-]{0,37}[A-Za-z0-9])?\/(?!\.{1,2}$)(?!.*\.git$)(?=[A-Za-z0-9._-]*[A-Za-z0-9])[A-Za-z0-9._-]{1,100}$/u.test(value)
  ) throw new TypeError("Applicant source repository URL is invalid");
  return value;
}

function gitSha(value: unknown, label: string): string {
  if (typeof value !== "string" || !/^[0-9a-f]{40}$/u.test(value)) {
    throw new TypeError(`${label} is invalid`);
  }
  return value;
}

function positiveSafeInteger(value: unknown, label: string): number {
  if (!Number.isSafeInteger(value) || (value as number) <= 0) throw new TypeError(`${label} is invalid`);
  return value as number;
}

function nonnegativeSafeInteger(value: unknown, label: string): number {
  if (!Number.isSafeInteger(value) || (value as number) < 0) throw new TypeError(`${label} is invalid`);
  return value as number;
}

function eip55Address(value: unknown, label: string): string {
  if (typeof value !== "string" || !/^0x[0-9a-fA-F]{40}$/u.test(value) || BigInt(value) === 0n) {
    throw new TypeError(`${label} is invalid`);
  }
  const lower = value.slice(2).toLowerCase();
  const hash = keccak256(Buffer.from(lower, "ascii")).slice(2);
  let checksum = "0x";
  for (let index = 0; index < lower.length; index += 1) {
    const character = lower[index]!;
    checksum += /[a-f]/u.test(character) && Number.parseInt(hash[index]!, 16) >= 8
      ? character.toUpperCase()
      : character;
  }
  if (value !== checksum) throw new TypeError(`${label} is not canonical EIP-55`);
  return value;
}

function normalizeEip55Address(value: unknown, label: string): EvmAddressV1 {
  return eip55Address(value, label).toLowerCase() as EvmAddressV1;
}

function evmAddress(value: unknown, label: string, allowZero: boolean): EvmAddressV1 {
  if (typeof value !== "string" || !/^0x[0-9a-fA-F]{40}$/u.test(value)) {
    throw new TypeError(`${label} is invalid`);
  }
  const normalized = value.toLowerCase() as EvmAddressV1;
  if (!allowZero && BigInt(normalized) === 0n) throw new TypeError(`${label} is zero`);
  return normalized;
}

function assertExactKeys(
  value: unknown,
  expected: readonly string[],
  label: string,
): asserts value is Record<string, JsonValue> {
  if (value === null || typeof value !== "object" || Array.isArray(value)) {
    throw new TypeError(`${label} is not an object`);
  }
  const actual = Reflect.ownKeys(value);
  const stringKeys = actual.filter((key): key is string => typeof key === "string").sort(compare);
  const wanted = [...expected].sort(compare);
  if (
    actual.length !== stringKeys.length
    || stringKeys.length !== wanted.length
    || stringKeys.some((key, index) => key !== wanted[index])
  ) throw new TypeError(`${label} has unexpected fields`);
}

function compare(left: string, right: string): number {
  return Buffer.compare(Buffer.from(left, "utf8"), Buffer.from(right, "utf8"));
}

function deepFreeze<T>(value: T): T {
  if (value !== null && typeof value === "object" && !Object.isFrozen(value)) {
    for (const nested of Object.values(value as Record<string, unknown>)) deepFreeze(nested);
    Object.freeze(value);
  }
  return value;
}
