import { canonicalizeJson } from "../../domain/canonical-json.js";
import { canonicalSha256 } from "../../domain/hashing.js";
import type { Sha256Digest } from "../../domain/types.js";
import {
  createLaunchPermitV1,
  computePermitDigestV1,
  computeSafeMessageSigningDigestV1,
  type CanonicalCustomGraphLaunchV1,
  type StampRequestV1,
} from "./abi-codec.js";
import {
  computeGitHubApprovalBindingHashV1,
  computeRouterApprovalRevisionHashV1,
} from "./github-approval.js";
import {
  PRODUCTION_ROUTER_SELF_SERVICE_BINDING_V1 as BINDING,
  type EvmAddressV1,
  type EvmBytes32V1,
  type EvmHexV1,
} from "./production-binding.js";
import type { ManualGitHubRouterSignatureRequestV1 } from "./self-service.js";

const PRODUCTION_INTAKE_FULL_NAME = "0xprogrammable/hookbuilder" as const;

export interface ManualRouterLaunchPreparationV1 {
  readonly schemaVersion: "programmable.manual-router-launch-preparation.v1";
  readonly authority: Readonly<{
    chainId: "1";
    router: Readonly<{ address: EvmAddressV1; runtimeKeccak256: EvmBytes32V1 }>;
    safe: Readonly<{
      address: EvmAddressV1;
      runtimeKeccak256: EvmBytes32V1;
      admin: EvmAddressV1;
    }>;
  }>;
  readonly source: Readonly<{
    repositoryId: string;
    repositoryFullName: typeof PRODUCTION_INTAKE_FULL_NAME;
    pullRequestNumber: number;
    headRepositoryId: string;
    headSha: string;
    treeSha: string;
    applicantGitHubUserId: string;
    compileInputHash: Sha256Digest;
    planHash: Sha256Digest;
    review: Readonly<{
      bindingHash: Sha256Digest;
      approvalId: EvmBytes32V1;
      approvalVersion: string;
      reviewArtifactHash: EvmBytes32V1;
      configurationHash: EvmBytes32V1;
      evidenceDigest: EvmBytes32V1;
      policyHash: EvmBytes32V1;
      authorizedPrincipalHash: EvmBytes32V1;
      verifiedAtEpochSeconds: string;
    }>;
  }>;
  readonly launch: Readonly<{
    launchWallet: EvmAddressV1;
    kind: 1;
    routePayload: EvmHexV1;
    routePayloadHash: EvmBytes32V1;
    routeNonce: EvmBytes32V1;
    expectedResultHash: EvmBytes32V1;
    stampRequest: Readonly<StampRequestV1>;
    stampRequestHash: EvmBytes32V1;
    valueWei: string;
    validAfter: string;
    deadline: string;
    /** Observation only; the applicant wallet assigns its own transaction nonce. */
    pendingNonceAtPreparation: EvmHexV1;
  }>;
  readonly authoritySignatureRequest: Readonly<ManualGitHubRouterSignatureRequestV1>;
}

export function createManualRouterLaunchPreparationV1(input: Readonly<{
  signatureRequest: ManualGitHubRouterSignatureRequestV1;
  launch: CanonicalCustomGraphLaunchV1;
}>): Readonly<ManualRouterLaunchPreparationV1> {
  const request = input.signatureRequest;
  const launch = input.launch;
  const claim = request.approval.claim;
  const revision = claim.approvalRevision;
  const rebuiltPermit = createLaunchPermitV1({
    launch,
    launchWallet: request.launchWallet,
    validAfter: request.permit.validAfter,
    deadline: request.permit.deadline,
  });
  const { requestHash: _, ...requestCore } = request;
  if (
    request.schemaVersion !== "programmable.manual-github-router-signature-request.v1"
    || request.requestHash !== canonicalSha256(request.schemaVersion, requestCore)
    || request.approval.approvalBindingHash !== computeGitHubApprovalBindingHashV1(claim)
    || request.compileRequest.schemaVersion !== "programmable.router-custom-graph-compile-request.v3"
    || request.compileRequest.authorizedLauncher !== BINDING.router.address
    || request.compileRequest.routeNamespace !== launch.plan.route.routeNamespace
    || request.compileRequest.routeNonce !== launch.plan.route.routeNonce
    || request.compileRequest.pullRequestNumber !== claim.pullRequestNumber
    || request.compileRequest.approvalRevisionHash
      !== computeRouterApprovalRevisionHashV1(revision)
    || request.planHash !== launch.planHash
    || request.compileInputHash !== request.compileRequest.compileInputHash
    || request.launchWallet !== claim.approvedLaunchWallet
    || canonicalizeJson(request.permit) !== canonicalizeJson(rebuiltPermit)
    || request.permitDigest !== computePermitDigestV1(request.permit)
    || request.safeMessageDigest !== computeSafeMessageSigningDigestV1(request.permitDigest)
    || request.finalizedAnchor.anchorHash !== request.preflight.finalizedAnchor.anchorHash
    || request.preflight.targetCount !== launch.plan.route.expectedOutputs.length
  ) throw new TypeError("manual Router launch preparation inputs are not exactly bound");
  const preparation = {
    schemaVersion: "programmable.manual-router-launch-preparation.v1" as const,
    authority: {
      chainId: "1" as const,
      router: {
        address: BINDING.router.address,
        runtimeKeccak256: BINDING.router.runtimeKeccak256,
      },
      safe: {
        address: BINDING.permitAuthoritySafe.address,
        runtimeKeccak256: BINDING.permitAuthoritySafe.runtimeKeccak256,
        admin: BINDING.permitAuthoritySafe.manualOwner,
      },
    },
    source: {
      repositoryId: claim.repositoryId,
      repositoryFullName: PRODUCTION_INTAKE_FULL_NAME,
      pullRequestNumber: claim.pullRequestNumber,
      headRepositoryId: claim.headRepositoryId,
      headSha: claim.headSha,
      treeSha: claim.treeSha,
      applicantGitHubUserId: claim.approvedGitHubUserId,
      compileInputHash: claim.compileInputHash,
      planHash: claim.planHash,
      review: {
        bindingHash: request.approval.approvalBindingHash,
        approvalId: revision.approvalId,
        approvalVersion: revision.approvalVersion,
        reviewArtifactHash: revision.reviewArtifactHash,
        configurationHash: revision.configurationHash,
        evidenceDigest: revision.evidenceDigest,
        policyHash: revision.policyHash,
        authorizedPrincipalHash: revision.authorizedPrincipalHash,
        verifiedAtEpochSeconds: request.approval.verifiedAtEpochSeconds,
      },
    },
    launch: {
      launchWallet: request.launchWallet,
      kind: 1 as const,
      routePayload: launch.routePayload,
      routePayloadHash: launch.routePayloadHash,
      routeNonce: launch.plan.route.routeNonce,
      expectedResultHash: launch.expectedResultHash,
      stampRequest: launch.plan.stampRequest,
      stampRequestHash: launch.stampRequestHash,
      valueWei: launch.plan.valueWei,
      validAfter: request.permit.validAfter,
      deadline: request.permit.deadline,
      pendingNonceAtPreparation: toQuantity(request.preflight.pendingNonce),
    },
    authoritySignatureRequest: request,
  };
  return deepFreeze(preparation);
}

export function assertManualRouterLaunchPreparationV1(
  raw: unknown,
  input: Readonly<{
    signatureRequest: ManualGitHubRouterSignatureRequestV1;
    launch: CanonicalCustomGraphLaunchV1;
  }>,
): Readonly<ManualRouterLaunchPreparationV1> {
  const rebuilt = createManualRouterLaunchPreparationV1(input);
  if (canonicalizeJson(raw) !== canonicalizeJson(rebuilt)) {
    throw new TypeError("manual Router launch preparation is invalid");
  }
  return rebuilt;
}

export function computeManualRouterLaunchPreparationSha256V1(
  preparation: ManualRouterLaunchPreparationV1,
): Sha256Digest {
  return canonicalSha256("programmable.manual-router-launch-preparation.v1", preparation);
}

function toQuantity(value: string): EvmHexV1 {
  if (!/^(?:0|[1-9][0-9]*)$/u.test(value)) throw new TypeError("pending nonce is invalid");
  const parsed = BigInt(value);
  if (parsed >= 1n << 256n) throw new TypeError("pending nonce exceeds uint256");
  return `0x${parsed.toString(16)}`;
}

function deepFreeze<T>(value: T): T {
  if (value !== null && typeof value === "object" && !Object.isFrozen(value)) {
    for (const nested of Object.values(value as Record<string, unknown>)) deepFreeze(nested);
    Object.freeze(value);
  }
  return value;
}
