import {
  RouterRpcExecutionRevertV1,
  type RouterReadRpcProviderV1,
} from "./rpc.js";

const MAXIMUM_RPC_RESPONSE_BYTES = 4 * 1_024 * 1_024;
const ALLOWED_METHODS = new Set([
  "eth_blockNumber",
  "eth_call",
  "eth_chainId",
  "eth_getBalance",
  "eth_getBlockByHash",
  "eth_getBlockByNumber",
  "eth_getCode",
  "eth_getLogs",
  "eth_getStorageAt",
  "eth_getTransactionByHash",
  "eth_getTransactionCount",
  "eth_getTransactionReceipt",
]);

export type ManualRouterProductionRpcFamilyV1 = "alchemy" | "quicknode";

export const MANUAL_ROUTER_ALCHEMY_PROVIDER_ID_V1 =
  "manual-router-rpc:alchemy-mainnet-v1" as const;
export const MANUAL_ROUTER_QUICKNODE_PROVIDER_ID_V1 =
  "manual-router-rpc:quicknode-mainnet-v1" as const;
export const MANUAL_ROUTER_ALCHEMY_TRUST_DOMAIN_V1 = "alchemy.com" as const;
export const MANUAL_ROUTER_QUICKNODE_TRUST_DOMAIN_V1 = "quiknode.pro" as const;
export const MANUAL_ROUTER_ALCHEMY_RPC_ENV_V1 =
  "PROGRAMMABLE_ALCHEMY_MAINNET_RPC_URL" as const;
export const MANUAL_ROUTER_QUICKNODE_RPC_ENV_V1 =
  "PROGRAMMABLE_QUICKNODE_MAINNET_RPC_URL" as const;

/**
 * Secret-bearing JSON-RPC transport for the one-shot operator CLI. Endpoints
 * are accepted only for the two code-owned production provider families. No
 * endpoint or endpoint-derived value is exposed through provider identity or
 * errors; the CLI obtains both URLs from its environment, never argv.
 */
export class HttpRouterReadRpcProviderV1 implements RouterReadRpcProviderV1 {
  readonly providerId: string;
  readonly trustDomain: string;
  readonly #endpoint: string;
  readonly #fetch: typeof fetch;
  #requestId = 0;

  constructor(input: Readonly<{
    endpoint: string;
    family: ManualRouterProductionRpcFamilyV1;
    fetch: typeof fetch;
  }>) {
    const endpoint = productionRpcEndpoint(input.endpoint, input.family);
    this.#endpoint = endpoint;
    this.#fetch = input.fetch;
    this.trustDomain = input.family === "alchemy"
      ? MANUAL_ROUTER_ALCHEMY_TRUST_DOMAIN_V1
      : MANUAL_ROUTER_QUICKNODE_TRUST_DOMAIN_V1;
    this.providerId = input.family === "alchemy"
      ? MANUAL_ROUTER_ALCHEMY_PROVIDER_ID_V1
      : MANUAL_ROUTER_QUICKNODE_PROVIDER_ID_V1;
  }

  async request(method: string, params: readonly unknown[]): Promise<unknown> {
    if (!ALLOWED_METHODS.has(method)) throw new TypeError("manual Router RPC method is not allowed");
    if (!Array.isArray(params)) throw new TypeError("manual Router RPC params are invalid");
    const id = ++this.#requestId;
    let response: Response;
    try {
      response = await this.#fetch(this.#endpoint, {
        method: "POST",
        redirect: "error",
        signal: AbortSignal.timeout(15_000),
        headers: {
          accept: "application/json",
          "content-type": "application/json",
          "user-agent": "programmable-manual-router-operator-v1",
        },
        body: JSON.stringify({ jsonrpc: "2.0", id, method, params }),
      });
    } catch {
      throw new TypeError("manual Router RPC request failed");
    }
    const declared = response.headers.get("content-length");
    if (declared !== null && (!/^\d+$/u.test(declared) || Number(declared) > MAXIMUM_RPC_RESPONSE_BYTES)) {
      throw new TypeError("manual Router RPC response exceeded its byte limit");
    }
    const body = await response.text();
    if (Buffer.byteLength(body, "utf8") > MAXIMUM_RPC_RESPONSE_BYTES) {
      throw new TypeError("manual Router RPC response exceeded its byte limit");
    }
    if (response.status !== 200) {
      throw new TypeError(`manual Router RPC returned HTTP ${response.status}`);
    }
    let parsed: unknown;
    try {
      parsed = JSON.parse(body) as unknown;
    } catch (error) {
      throw new TypeError("manual Router RPC response is not JSON", { cause: error });
    }
    const envelope = rpcEnvelope(parsed);
    const envelopeKeys = Object.keys(envelope).sort();
    if (
      envelopeKeys.length !== 3
      || (
        envelopeKeys.join(",") !== "id,jsonrpc,result"
        && envelopeKeys.join(",") !== "error,id,jsonrpc"
      )
    ) throw new TypeError("manual Router RPC response has unexpected fields");
    if (envelope.jsonrpc !== "2.0" || envelope.id !== id) {
      throw new TypeError("manual Router RPC response identity is invalid");
    }
    const hasResult = Object.prototype.hasOwnProperty.call(envelope, "result");
    const hasError = Object.prototype.hasOwnProperty.call(envelope, "error");
    if (hasResult === hasError) throw new TypeError("manual Router RPC response disposition is invalid");
    if (hasResult) return envelope.result;
    const error = rpcEnvelope(envelope.error);
    const message = typeof error.message === "string" ? error.message : "";
    if (
      method === "eth_call"
      && typeof error.code === "number"
      && Number.isSafeInteger(error.code)
      && /(?:execution\s+reverted|\brevert(?:ed)?\b)/iu.test(message)
    ) throw new RouterRpcExecutionRevertV1("manual Router eth_call reverted");
    throw new TypeError("manual Router RPC returned an execution error");
  }
}

function productionRpcEndpoint(
  raw: string,
  family: ManualRouterProductionRpcFamilyV1,
): string {
  if (
    typeof raw !== "string"
    || raw.length === 0
    || raw.length > 2_048
    || raw !== raw.trim()
  ) {
    throw new TypeError("manual Router RPC endpoint is invalid");
  }
  let parsed: URL;
  try {
    parsed = new URL(raw);
  } catch {
    throw new TypeError("manual Router RPC endpoint is invalid");
  }
  const hostname = parsed.hostname.toLowerCase();
  const familyMatches = family === "alchemy"
    ? hostname === "eth-mainnet.g.alchemy.com"
    : /^(?:[a-z0-9-]+\.)+quiknode\.pro$/u.test(hostname);
  if (
    parsed.protocol !== "https:"
    || parsed.username !== ""
    || parsed.password !== ""
    || parsed.search !== ""
    || parsed.hash !== ""
    || parsed.port !== ""
    || parsed.pathname === "/"
    || !familyMatches
  ) throw new TypeError("manual Router RPC endpoint does not match its production provider family");
  return parsed.href;
}

function rpcEnvelope(raw: unknown): Record<string, unknown> {
  if (raw === null || typeof raw !== "object" || Array.isArray(raw)) {
    throw new TypeError("manual Router RPC response is not an object");
  }
  return raw as Record<string, unknown>;
}
