import { createHash } from "node:crypto";

import { canonicalSha256 } from "../../domain/hashing.js";
import type { Sha256Digest } from "../../domain/types.js";
import {
  GITHUB_REST_ACCEPT,
  GITHUB_REST_API_VERSION,
  GITHUB_REST_USER_AGENT,
} from "../../github-rest/types.js";
import {
  assertHookbuilderApplicantRequestEvidenceV1,
  type HookbuilderApplicantRequestEvidenceV1,
} from "./hookbuilder-applicant-request.js";
import type { EvmAddressV1, EvmBytes32V1 } from "./production-binding.js";

const PRODUCTION_GITHUB_IDENTITY = Object.freeze({
  repositoryId: "1320085947",
  owner: "0xprogrammable",
  name: "hookbuilder",
});

export interface ProductionGitHubApprovalBindingV1 {
  readonly schemaVersion: "programmable.router-github-approval-binding.v1";
  readonly repositoryId: "1320085947";
  readonly owner: "0xprogrammable";
  readonly name: "hookbuilder";
}

export interface GitHubRouterApprovalClaimV1 {
  readonly schemaVersion: "programmable.github-router-launch-approval-claim.v3";
  readonly repositoryId: string;
  readonly pullRequestNumber: number;
  readonly headRepositoryId: string;
  readonly headSha: string;
  readonly treeSha: string;
  readonly approvedGitHubUserId: string;
  readonly approvedLaunchWallet: EvmAddressV1;
  /** Hash of the complete compiler input before routeNonce-dependent outputs. */
  readonly compileInputHash: Sha256Digest;
  readonly planHash: Sha256Digest;
  readonly approvalRevision: Readonly<RouterApprovalRevisionV1>;
}

export interface VerifiedGitHubRouterApprovalV1 {
  readonly schemaVersion: "programmable.verified-github-router-launch-approval.v6";
  readonly claim: Readonly<GitHubRouterApprovalClaimV1>;
  readonly approvalBindingHash: Sha256Digest;
  readonly pullRequestAuthorGitHubUserId: string;
  readonly pullRequestAuthorGitHubLogin: string;
  readonly pullRequestHeadRepositoryUrl: string;
  readonly sourceRepositoryId: string;
  readonly sourceRepositoryUrl: string;
  readonly sourceCommitSha: string;
  readonly sourceTreeSha: string;
  readonly pullRequestState: "open" | "merged";
  readonly verifiedAtEpochSeconds: string;
}

export interface GitHubApplicantSourceRevisionV1 {
  readonly repositoryId: string;
  readonly repositoryUrl: string;
  readonly commitSha: string;
  readonly treeSha: string;
}

/**
 * Immutable review/currentness axes. This remains the exact existing V2 review
 * record shape; it is deliberately independent of the discarded V2
 * contract-owner/KMS signing design.
 */
export interface RouterApprovalRevisionV1 {
  readonly schemaVersion: "programmable.router-approval-revision.v2";
  readonly approvalId: EvmBytes32V1;
  readonly repositoryId: string;
  readonly headSha: `0x${string}`;
  readonly treeSha: `0x${string}`;
  readonly reviewArtifactHash: EvmBytes32V1;
  readonly configurationHash: EvmBytes32V1;
  readonly evidenceDigest: EvmBytes32V1;
  readonly policyHash: EvmBytes32V1;
  readonly approvalVersion: string;
  readonly authorizedPrincipalHash: EvmBytes32V1;
}

export interface GitHubReadTokenProviderV1 {
  /** Server-held, read-only token. Applicant identity is authenticated separately. */
  getReadToken(): Promise<Readonly<{ token: string | null }>>;
}

export interface GitHubApprovalCurrentnessVerifierV1 {
  verifyCurrentApproval(
    claim: GitHubRouterApprovalClaimV1,
    applicantRequest: HookbuilderApplicantRequestEvidenceV1,
    sourceRevision: GitHubApplicantSourceRevisionV1,
  ): Promise<Readonly<VerifiedGitHubRouterApprovalV1>>;
}

export function loadProductionGitHubApprovalBindingV1(
  env: Readonly<Record<string, string | undefined>>,
): Readonly<ProductionGitHubApprovalBindingV1> {
  const configured = env.PROGRAMMABLE_ROUTER_GITHUB_REPOSITORY_ID;
  if (configured !== undefined && configured !== PRODUCTION_GITHUB_IDENTITY.repositoryId) {
    throw new TypeError("PROGRAMMABLE_ROUTER_GITHUB_REPOSITORY_ID does not match the code-owned production binding");
  }
  return Object.freeze({
    schemaVersion: "programmable.router-github-approval-binding.v1" as const,
    ...PRODUCTION_GITHUB_IDENTITY,
  });
}

export function assertProductionGitHubApprovalBindingV1(
  raw: ProductionGitHubApprovalBindingV1,
): Readonly<ProductionGitHubApprovalBindingV1> {
  assertExactKeys(raw, [
    "name", "owner", "repositoryId", "schemaVersion",
  ], "production GitHub approval binding");
  if (
    raw.schemaVersion !== "programmable.router-github-approval-binding.v1"
    || raw.repositoryId !== PRODUCTION_GITHUB_IDENTITY.repositoryId
    || raw.owner !== PRODUCTION_GITHUB_IDENTITY.owner
    || raw.name !== PRODUCTION_GITHUB_IDENTITY.name
  ) throw new TypeError("production GitHub approval binding identity drifted");
  return Object.freeze({
    schemaVersion: raw.schemaVersion,
    ...PRODUCTION_GITHUB_IDENTITY,
  });
}

export function canonicalGitHubApprovalClaimV1(
  raw: GitHubRouterApprovalClaimV1,
): Readonly<GitHubRouterApprovalClaimV1> {
  assertExactKeys(raw, [
    "approvalRevision", "approvedGitHubUserId", "approvedLaunchWallet", "compileInputHash",
    "headRepositoryId", "headSha", "planHash", "pullRequestNumber", "repositoryId",
    "schemaVersion", "treeSha",
  ], "GitHub approval claim");
  if (raw.schemaVersion !== "programmable.github-router-launch-approval-claim.v3") {
    throw new TypeError("GitHub approval claim schema is invalid");
  }
  if (raw.repositoryId !== PRODUCTION_GITHUB_IDENTITY.repositoryId) {
    throw new TypeError("GitHub approval claim is not bound to the production intake repository");
  }
  if (!Number.isSafeInteger(raw.pullRequestNumber) || raw.pullRequestNumber <= 0) {
    throw new TypeError("GitHub approval pull-request number is invalid");
  }
  const approvalRevision = canonicalRouterApprovalRevisionV1(raw.approvalRevision);
  const headSha = gitSha(raw.headSha, "GitHub approval head SHA");
  const treeSha = gitSha(raw.treeSha, "GitHub approval tree SHA");
  if (
    approvalRevision.repositoryId !== raw.repositoryId
    || approvalRevision.headSha !== `0x${headSha}`
    || approvalRevision.treeSha !== `0x${treeSha}`
  ) throw new TypeError("Router approval revision does not match the claimed GitHub revision");
  return deepFreeze({
    schemaVersion: raw.schemaVersion,
    repositoryId: numericId(raw.repositoryId, "GitHub approval repository id"),
    pullRequestNumber: raw.pullRequestNumber,
    headRepositoryId: numericId(raw.headRepositoryId, "GitHub approval head repository id"),
    headSha,
    treeSha,
    approvedGitHubUserId: numericId(raw.approvedGitHubUserId, "approved GitHub user id"),
    approvedLaunchWallet: address(raw.approvedLaunchWallet, "approved launch wallet"),
    compileInputHash: sha256(raw.compileInputHash, "GitHub approval compile-input hash"),
    planHash: sha256(raw.planHash, "GitHub approval plan hash"),
    approvalRevision,
  });
}

export function computeGitHubApprovalBindingHashV1(
  claim: GitHubRouterApprovalClaimV1,
): Sha256Digest {
  return canonicalSha256(
    "programmable.github-router-launch-approval.v3",
    canonicalGitHubApprovalClaimV1(claim),
  );
}

export function computeRouterApprovalRevisionHashV1(
  revision: RouterApprovalRevisionV1,
): Sha256Digest {
  return canonicalSha256(
    "programmable.router-approval-revision.v2",
    canonicalRouterApprovalRevisionV1(revision),
  );
}

export function canonicalGitHubApplicantSourceRevisionV1(
  raw: GitHubApplicantSourceRevisionV1,
): Readonly<GitHubApplicantSourceRevisionV1> {
  assertExactKeys(raw, [
    "commitSha", "repositoryId", "repositoryUrl", "treeSha",
  ], "GitHub Applicant source revision");
  return Object.freeze({
    repositoryId: numericId(raw.repositoryId, "Applicant source repository id"),
    repositoryUrl: publicGitHubRepositoryUrl(raw.repositoryUrl),
    commitSha: gitSha(raw.commitSha, "Applicant source commit SHA"),
    treeSha: gitSha(raw.treeSha, "Applicant source tree SHA"),
  });
}

export function assertVerifiedGitHubRouterApprovalV1(
  raw: VerifiedGitHubRouterApprovalV1,
): Readonly<VerifiedGitHubRouterApprovalV1> {
  assertExactKeys(raw, [
    "approvalBindingHash", "claim", "pullRequestAuthorGitHubLogin",
    "pullRequestAuthorGitHubUserId", "pullRequestHeadRepositoryUrl", "pullRequestState",
    "schemaVersion", "sourceCommitSha", "sourceRepositoryId", "sourceRepositoryUrl",
    "sourceTreeSha", "verifiedAtEpochSeconds",
  ], "verified GitHub Router approval");
  if (raw.schemaVersion !== "programmable.verified-github-router-launch-approval.v6") {
    throw new TypeError("verified GitHub Router approval schema is invalid");
  }
  const claim = canonicalGitHubApprovalClaimV1(raw.claim);
  const approvalBindingHash = computeGitHubApprovalBindingHashV1(claim);
  const pullRequestAuthorGitHubUserId = numericId(
    raw.pullRequestAuthorGitHubUserId,
    "pull-request author GitHub user id",
  );
  if (
    raw.approvalBindingHash !== approvalBindingHash
    || pullRequestAuthorGitHubUserId !== claim.approvedGitHubUserId
    || (raw.pullRequestState !== "open" && raw.pullRequestState !== "merged")
  ) throw new TypeError("verified GitHub Router approval binding is invalid");
  return deepFreeze({
    schemaVersion: raw.schemaVersion,
    claim,
    approvalBindingHash,
    pullRequestAuthorGitHubUserId,
    pullRequestAuthorGitHubLogin: requiredBoundedText(
      raw.pullRequestAuthorGitHubLogin,
      "pull-request author GitHub login",
      255,
    ),
    pullRequestHeadRepositoryUrl: publicGitHubRepositoryUrl(
      raw.pullRequestHeadRepositoryUrl,
    ),
    sourceRepositoryId: numericId(raw.sourceRepositoryId, "verified source repository id"),
    sourceRepositoryUrl: publicGitHubRepositoryUrl(raw.sourceRepositoryUrl),
    sourceCommitSha: gitSha(raw.sourceCommitSha, "verified source commit SHA"),
    sourceTreeSha: gitSha(raw.sourceTreeSha, "verified source tree SHA"),
    pullRequestState: raw.pullRequestState,
    verifiedAtEpochSeconds: uintString64(
      raw.verifiedAtEpochSeconds,
      "GitHub approval verification time",
    ),
  });
}

export function canonicalRouterApprovalRevisionV1(
  raw: RouterApprovalRevisionV1,
): Readonly<RouterApprovalRevisionV1> {
  assertExactKeys(raw, [
    "approvalId", "approvalVersion", "authorizedPrincipalHash", "configurationHash",
    "evidenceDigest", "headSha", "policyHash", "repositoryId", "reviewArtifactHash",
    "schemaVersion", "treeSha",
  ], "Router approval revision");
  if (raw.schemaVersion !== "programmable.router-approval-revision.v2") {
    throw new TypeError("Router approval revision schema is invalid");
  }
  return deepFreeze({
    schemaVersion: raw.schemaVersion,
    approvalId: nonzeroBytes32(raw.approvalId, "approval id"),
    repositoryId: uintString64(raw.repositoryId, "approval repository id"),
    headSha: bytes20(raw.headSha, "approval head SHA"),
    treeSha: bytes20(raw.treeSha, "approval tree SHA"),
    reviewArtifactHash: nonzeroBytes32(raw.reviewArtifactHash, "review artifact hash"),
    configurationHash: nonzeroBytes32(raw.configurationHash, "review configuration hash"),
    evidenceDigest: nonzeroBytes32(raw.evidenceDigest, "review evidence digest"),
    policyHash: nonzeroBytes32(raw.policyHash, "review policy hash"),
    approvalVersion: uintString64(raw.approvalVersion, "approval version"),
    authorizedPrincipalHash: nonzeroBytes32(
      raw.authorizedPrincipalHash,
      "authorized principal hash",
    ),
  });
}

/**
 * Narrow read-only GitHub currentness adapter. The human Safe-owner signature
 * is the sole launch authority. GitHub supplies immutable source provenance;
 * applicant session and linked-wallet authentication are enforced by the
 * Website boundary before an artifact can be read or reissued.
 */
export class GitHubRestApprovalCurrentnessVerifierV1 implements
  GitHubApprovalCurrentnessVerifierV1 {
  readonly #binding: Readonly<ProductionGitHubApprovalBindingV1>;
  readonly #readTokens: GitHubReadTokenProviderV1;
  readonly #fetch: typeof fetch;
  readonly #now: () => number;

  constructor(input: Readonly<{
    binding: Readonly<ProductionGitHubApprovalBindingV1>;
    readTokenProvider: GitHubReadTokenProviderV1;
    fetch: typeof fetch;
    nowEpochSeconds?: () => number;
  }>) {
    this.#binding = assertProductionGitHubApprovalBindingV1(input.binding);
    this.#readTokens = input.readTokenProvider;
    this.#fetch = input.fetch;
    this.#now = input.nowEpochSeconds ?? (() => Math.floor(Date.now() / 1_000));
    Object.freeze(this);
  }

  async verifyCurrentApproval(
    rawClaim: GitHubRouterApprovalClaimV1,
    rawApplicantRequest: HookbuilderApplicantRequestEvidenceV1,
    rawSourceRevision: GitHubApplicantSourceRevisionV1,
  ): Promise<Readonly<VerifiedGitHubRouterApprovalV1>> {
    const claim = canonicalGitHubApprovalClaimV1(rawClaim);
    const applicant = assertHookbuilderApplicantRequestEvidenceV1(
      rawApplicantRequest,
    );
    const applicantRequest = applicant.evidence;
    const sourceRevision = canonicalGitHubApplicantSourceRevisionV1(rawSourceRevision);
    if (
      String(applicant.request.source.repositoryId) !== sourceRevision.repositoryId
      || applicant.request.source.repository !== sourceRevision.repositoryUrl
      || applicant.request.source.commit !== sourceRevision.commitSha
      || applicant.request.source.tree !== sourceRevision.treeSha
    ) throw new TypeError("GitHub source revision drifts from the exact Applicant request");
    const token = await this.#readTokens.getReadToken();
    const headers = authorizationHeaders(token.token);

    const [
      repositoryValue,
      pullValue,
      pullFilesValue,
      headRepositoryValue,
      headCommitValue,
      applicantFileValue,
      sourceRepositoryValue,
      sourceCommitValue,
    ] = await Promise.all([
      this.#get(`/repositories/${this.#binding.repositoryId}`, headers),
      this.#get(
        `/repositories/${this.#binding.repositoryId}/pulls/${claim.pullRequestNumber}`,
        headers,
      ),
      this.#get(
        `/repositories/${this.#binding.repositoryId}/pulls/${claim.pullRequestNumber}/files`
          + "?per_page=2&page=1",
        headers,
      ),
      this.#get(
        `/repositories/${claim.headRepositoryId}`,
        headers,
      ),
      this.#get(
        `/repositories/${claim.headRepositoryId}/git/commits/${claim.headSha}`,
        headers,
      ),
      this.#get(
        `/repositories/${claim.headRepositoryId}/contents/${githubPath(applicantRequest.requestPath)}`
          + `?ref=${claim.headSha}`,
        headers,
      ),
      this.#get(`/repositories/${sourceRevision.repositoryId}`, headers),
      this.#get(
        `/repositories/${sourceRevision.repositoryId}/git/commits/${sourceRevision.commitSha}`,
        headers,
      ),
    ]);

    const repository = object(repositoryValue, "GitHub repository");
    if (
      numericId(repository.id, "observed GitHub repository id") !== this.#binding.repositoryId
      || text(repository.name, "observed GitHub repository name") !== this.#binding.name
      || text(object(repository.owner, "GitHub repository owner").login, "GitHub owner login")
        !== this.#binding.owner
      || repository.visibility !== "public"
      || repository.archived !== false
      || repository.disabled !== false
    ) throw new TypeError("GitHub intake repository identity or public availability drifted");

    const pull = object(pullValue, "GitHub pull request");
    const base = object(pull.base, "GitHub pull-request base");
    const head = object(pull.head, "GitHub pull-request head");
    const author = object(pull.user, "GitHub pull-request author");
    const observedBaseRepository = object(base.repo, "GitHub pull-request base repository");
    const observedHeadRepository = object(head.repo, "GitHub pull-request head repository");
    const headRepository = object(headRepositoryValue, "GitHub pull-request head repository");
    const sourceRepository = object(sourceRepositoryValue, "GitHub Applicant source repository");
    const state = pull.state === "open" && pull.merged === false
      ? "open"
      : pull.state === "closed" && pull.merged === true ? "merged" : null;
    if (
      numericId(pull.number, "observed pull-request number") !== String(claim.pullRequestNumber)
      || numericId(observedBaseRepository.id, "observed pull-request base repository id")
        !== claim.repositoryId
      || numericId(observedHeadRepository.id, "observed pull-request head repository id")
        !== claim.headRepositoryId
      || numericId(headRepository.id, "observed pull-request head repository id")
        !== claim.headRepositoryId
      || headRepository.visibility !== "public"
      || headRepository.archived !== false
      || headRepository.disabled !== false
      || gitSha(head.sha, "observed pull-request head SHA") !== claim.headSha
      || pull.changed_files !== 1
      || pull.draft !== false
      || state === null
      || numericId(author.id, "observed pull-request author id") !== claim.approvedGitHubUserId
    ) throw new TypeError("GitHub pull request no longer matches the exact approved revision and user");

    const commit = object(headCommitValue, "GitHub pull-request head commit");
    if (
      gitSha(commit.sha, "observed GitHub commit SHA") !== claim.headSha
      || gitSha(object(commit.tree, "GitHub commit tree").sha, "observed GitHub tree SHA")
        !== claim.treeSha
    ) throw new TypeError("GitHub commit tree no longer matches the approved revision");

    assertExactApplicantFileV1(applicantFileValue, applicantRequest);
    assertExactApplicantPullRequestDiffV1(
      pullFilesValue,
      applicantFileValue,
      applicantRequest,
    );

    if (
      numericId(sourceRepository.id, "observed Applicant source repository id")
        !== sourceRevision.repositoryId
      || publicGitHubRepositoryUrl(sourceRepository.html_url) !== sourceRevision.repositoryUrl
      || sourceRepository.visibility !== "public"
      || sourceRepository.archived !== false
      || sourceRepository.disabled !== false
    ) throw new TypeError("GitHub Applicant source repository identity or availability drifted");
    const sourceCommit = object(sourceCommitValue, "GitHub Applicant source commit");
    if (
      gitSha(sourceCommit.sha, "observed Applicant source commit SHA")
        !== sourceRevision.commitSha
      || gitSha(
        object(sourceCommit.tree, "GitHub Applicant source commit tree").sha,
        "observed Applicant source tree SHA",
      ) !== sourceRevision.treeSha
    ) throw new TypeError("GitHub Applicant source commit tree drifted");

    const verifiedAt = this.#now();
    const verifiedAtEpochSeconds = canonicalEpochSeconds(verifiedAt, "GitHub verification time");
    const authorId = numericId(author.id, "GitHub pull-request author id");
    const authorLogin = text(author.login, "GitHub pull-request author login");
    return deepFreeze({
      schemaVersion: "programmable.verified-github-router-launch-approval.v6" as const,
      claim,
      approvalBindingHash: computeGitHubApprovalBindingHashV1(claim),
      pullRequestAuthorGitHubUserId: authorId,
      pullRequestAuthorGitHubLogin: authorLogin,
      pullRequestHeadRepositoryUrl: publicGitHubRepositoryUrl(headRepository.html_url),
      sourceRepositoryId: sourceRevision.repositoryId,
      sourceRepositoryUrl: sourceRevision.repositoryUrl,
      sourceCommitSha: sourceRevision.commitSha,
      sourceTreeSha: sourceRevision.treeSha,
      pullRequestState: state,
      verifiedAtEpochSeconds,
    });
  }

  async #get(path: string, headers: Readonly<Record<string, string>>): Promise<unknown> {
    const response = await this.#fetch(`https://api.github.com${path}`, {
      method: "GET",
      redirect: "error",
      signal: AbortSignal.timeout(10_000),
      headers,
    });
    const contentLength = response.headers.get("content-length");
    if (contentLength !== null && Number(contentLength) > 1_048_576) {
      throw new TypeError("GitHub response exceeded the self-service metadata limit");
    }
    const body = await response.text();
    if (Buffer.byteLength(body, "utf8") > 1_048_576) {
      throw new TypeError("GitHub response exceeded the self-service metadata limit");
    }
    if (response.status !== 200) throw new TypeError(`GitHub read failed with status ${response.status}`);
    try {
      return JSON.parse(body) as unknown;
    } catch {
      throw new TypeError("GitHub response was not JSON");
    }
  }
}

function assertExactApplicantPullRequestDiffV1(
  rawFiles: unknown,
  rawFile: unknown,
  expected: Readonly<HookbuilderApplicantRequestEvidenceV1>,
): void {
  const files = array(rawFiles, "GitHub pull-request files");
  if (files.length !== 1) {
    throw new TypeError("GitHub Applicant pull request must change exactly one file");
  }
  const diff = object(files[0], "GitHub Applicant pull-request file");
  const file = object(rawFile, "GitHub Applicant request file");
  if (
    diff.filename !== expected.requestPath
    || (diff.status !== "added" && diff.status !== "modified")
    || diff.previous_filename !== undefined
    || gitSha(diff.sha, "GitHub Applicant pull-request blob SHA")
      !== gitSha(file.sha, "GitHub Applicant request blob SHA")
  ) throw new TypeError("GitHub Applicant pull-request file set drifted");
}

function assertExactApplicantFileV1(
  raw: unknown,
  expected: Readonly<HookbuilderApplicantRequestEvidenceV1>,
): void {
  const file = object(raw, "GitHub Applicant request file");
  if (
    file.type !== "file"
    || file.encoding !== "base64"
    || file.path !== expected.requestPath
    || nonnegativeSafeInteger(file.size, "GitHub Applicant request size")
      !== expected.rawByteLength
  ) throw new TypeError("GitHub Applicant request path or size drifted at the approved head");
  const content = decodeGitHubBase64(file.content, expected.rawByteLength);
  const expectedBytes = Buffer.from(expected.rawJsonUtf8, "utf8");
  if (!content.equals(expectedBytes)) {
    throw new TypeError("GitHub Applicant request bytes drifted at the approved head");
  }
  const blobHeader = Buffer.from(`blob ${content.byteLength}\0`, "utf8");
  const blobSha = createHash("sha1").update(blobHeader).update(content).digest("hex");
  if (gitSha(file.sha, "GitHub Applicant blob SHA") !== blobSha) {
    throw new TypeError("GitHub Applicant request blob identity is invalid");
  }
}

function decodeGitHubBase64(value: unknown, expectedBytes: number): Buffer {
  if (typeof value !== "string" || !/^(?:[A-Za-z0-9+/]{4}|\r?\n)*(?:[A-Za-z0-9+/]{2}==|[A-Za-z0-9+/]{3}=)?\r?\n?$/u.test(value)) {
    throw new TypeError("GitHub Applicant request content is not canonical base64");
  }
  const compact = value.replace(/[\r\n]/gu, "");
  const decoded = Buffer.from(compact, "base64");
  if (
    decoded.byteLength !== expectedBytes
    || decoded.toString("base64") !== compact
  ) throw new TypeError("GitHub Applicant request base64 bytes are invalid");
  return decoded;
}

function githubPath(value: string): string {
  return value.split("/").map((segment) => encodeURIComponent(segment)).join("/");
}

function authorizationHeaders(token: string | null): Readonly<Record<string, string>> {
  if (token !== null && !/^[\x21-\x7e]{20,4096}$/u.test(token)) {
    throw new TypeError("GitHub access token is invalid");
  }
  return Object.freeze({
    accept: GITHUB_REST_ACCEPT,
    ...(token === null ? {} : { authorization: `Bearer ${token}` }),
    "user-agent": GITHUB_REST_USER_AGENT,
    "x-github-api-version": GITHUB_REST_API_VERSION,
  });
}

function object(value: unknown, label: string): Record<string, unknown> {
  if (value === null || typeof value !== "object" || Array.isArray(value)) {
    throw new TypeError(`${label} is not an object`);
  }
  return value as Record<string, unknown>;
}

function array(value: unknown, label: string): readonly unknown[] {
  if (!Array.isArray(value)) throw new TypeError(`${label} is not an array`);
  return value;
}

function text(value: unknown, label: string): string {
  if (typeof value !== "string" || value.length === 0 || value.length > 255) {
    throw new TypeError(`${label} is invalid`);
  }
  return value;
}

function numericId(value: unknown, label: string): string {
  const normalized = typeof value === "number" && Number.isSafeInteger(value)
    ? String(value)
    : typeof value === "string" ? value : "";
  if (!/^[1-9][0-9]{0,19}$/u.test(normalized)) throw new TypeError(`${label} is invalid`);
  return normalized;
}

function gitSha(value: unknown, label: string): string {
  if (typeof value !== "string" || !/^[0-9a-f]{40}$/u.test(value)) {
    throw new TypeError(`${label} is not a lowercase SHA-1 object id`);
  }
  return value;
}

function sha256(value: unknown, label: string): Sha256Digest {
  if (typeof value !== "string" || !/^sha256:[0-9a-f]{64}$/u.test(value)) {
    throw new TypeError(`${label} is invalid`);
  }
  return value as Sha256Digest;
}

function address(value: unknown, label: string): EvmAddressV1 {
  if (typeof value !== "string" || !/^0x[0-9a-fA-F]{40}$/u.test(value)) {
    throw new TypeError(`${label} is invalid`);
  }
  const normalized = value.toLowerCase() as EvmAddressV1;
  if (BigInt(normalized) === 0n) throw new TypeError(`${label} is zero`);
  return normalized;
}

function nonzeroBytes32(value: unknown, label: string): EvmBytes32V1 {
  if (typeof value !== "string" || !/^0x[0-9a-f]{64}$/u.test(value) || BigInt(value) === 0n) {
    throw new TypeError(`${label} is invalid`);
  }
  return value as EvmBytes32V1;
}

function bytes20(value: unknown, label: string): `0x${string}` {
  if (typeof value !== "string" || !/^0x[0-9a-f]{40}$/u.test(value)) {
    throw new TypeError(`${label} is invalid`);
  }
  return value as `0x${string}`;
}

function uintString64(value: unknown, label: string): string {
  if (typeof value !== "string" || !/^(?:0|[1-9][0-9]*)$/u.test(value)) {
    throw new TypeError(`${label} is invalid`);
  }
  if (BigInt(value) >= 1n << 64n) throw new TypeError(`${label} exceeds uint64`);
  return value;
}

function requiredBoundedText(value: unknown, label: string, maximumBytes: number): string {
  if (
    typeof value !== "string"
    || value.length === 0
    || Buffer.byteLength(value, "utf8") > maximumBytes
    || /[\u0000-\u001f\u007f]/u.test(value)
  ) throw new TypeError(`${label} is required and invalid`);
  return value;
}

function publicGitHubRepositoryUrl(value: unknown): string {
  const url = requiredBoundedText(value, "GitHub source repository URL", 200);
  if (!/^https:\/\/github\.com\/[A-Za-z0-9-]+\/[A-Za-z0-9._-]+$/u.test(url)) {
    throw new TypeError("GitHub source repository URL is invalid");
  }
  return url;
}

function nonnegativeSafeInteger(value: unknown, label: string): number {
  if (!Number.isSafeInteger(value) || (value as number) < 0) throw new TypeError(`${label} is invalid`);
  return value as number;
}

function canonicalEpochSeconds(value: number, label: string): string {
  if (!Number.isSafeInteger(value) || value < 0) throw new TypeError(`${label} is invalid`);
  return String(value);
}

function assertExactKeys(
  value: unknown,
  expected: readonly string[],
  label: string,
): asserts value is Record<string, unknown> {
  if (value === null || typeof value !== "object" || Array.isArray(value)) {
    throw new TypeError(`${label} is not an object`);
  }
  const actual = Object.keys(value).sort();
  const required = [...expected].sort();
  if (actual.length !== required.length || actual.some((key, index) => key !== required[index])) {
    throw new TypeError(`${label} has unexpected fields`);
  }
}

function deepFreeze<T>(value: T): T {
  if (value !== null && typeof value === "object" && !Object.isFrozen(value)) {
    for (const nested of Object.values(value as Record<string, unknown>)) deepFreeze(nested);
    Object.freeze(value);
  }
  return value;
}
