import type { LaunchPermitV1 } from "./abi-codec.js";
import {
  PRODUCTION_ROUTER_SELF_SERVICE_BINDING_V1 as BINDING,
  type EvmAddressV1,
  type EvmHexV1,
} from "./production-binding.js";

export interface BrowserWalletRouterActionV1 {
  readonly schemaVersion: "programmable.browser-wallet-router-action.v1";
  readonly walletExecutionKind: "eoa-direct";
  readonly method: "eth_sendTransaction";
  readonly chainId: "0x1";
  /** Observation only. The wallet remains responsible for assigning the nonce. */
  readonly pendingNonceAtPreparation: string | null;
  readonly params: readonly [Readonly<{
    readonly from: EvmAddressV1;
    readonly to: EvmAddressV1;
    readonly data: EvmHexV1;
    readonly value: EvmHexV1;
  }>];
}

/**
 * Normalizes values returned by browser wallets and JSON-RPC clients. In
 * particular MetaMask may expose the same pending nonce as `223`, `"223"`, or
 * the JSON-RPC quantity `"0xdf"`.
 */
export function normalizePendingNonceV1(value: unknown): string {
  let parsed: bigint;
  if (typeof value === "number") {
    if (!Number.isSafeInteger(value) || value < 0) {
      throw new TypeError("pending nonce number is not a non-negative safe integer");
    }
    parsed = BigInt(value);
  } else if (typeof value === "bigint") {
    if (value < 0n) throw new TypeError("pending nonce bigint is negative");
    parsed = value;
  } else if (typeof value === "string") {
    if (/^(?:0|[1-9][0-9]*)$/u.test(value)) {
      parsed = BigInt(value);
    } else if (/^0x(?:0|[1-9a-f][0-9a-f]*)$/u.test(value)) {
      parsed = BigInt(value);
    } else {
      throw new TypeError("pending nonce string is neither canonical decimal nor JSON-RPC quantity");
    }
  } else {
    throw new TypeError("pending nonce has an unsupported representation");
  }
  if (parsed >= 1n << 256n) throw new TypeError("pending nonce exceeds uint256");
  return parsed.toString(10);
}

export function createBrowserWalletRouterActionV1(input: Readonly<{
  permit: LaunchPermitV1;
  calldata: EvmHexV1;
  pendingNonce?: unknown;
}>): Readonly<BrowserWalletRouterActionV1> {
  if (input.permit.chainId !== BINDING.chain.chainIdDecimal) {
    throw new TypeError("browser action permit is not bound to Ethereum mainnet");
  }
  if (input.permit.router !== BINDING.router.address) {
    throw new TypeError("browser action permit is not bound to the production Router");
  }
  if (!/^0x[0-9a-f]{40}$/u.test(input.permit.launchWallet)) {
    throw new TypeError("browser action launch wallet is invalid");
  }
  if (!/^0x[0-9a-f]+$/u.test(input.calldata) || input.calldata.slice(0, 10) !== BINDING.router.launchAndStampSelector) {
    throw new TypeError("browser action calldata is not exact launchAndStampV1 calldata");
  }
  const value = BigInt(input.permit.value);
  const action = {
    schemaVersion: "programmable.browser-wallet-router-action.v1" as const,
    walletExecutionKind: "eoa-direct" as const,
    method: "eth_sendTransaction" as const,
    chainId: BINDING.chain.chainIdHex,
    pendingNonceAtPreparation:
      input.pendingNonce === undefined ? null : normalizePendingNonceV1(input.pendingNonce),
    params: [{
      from: input.permit.launchWallet,
      to: BINDING.router.address,
      data: input.calldata,
      value: `0x${value.toString(16)}` as EvmHexV1,
    }] as const,
  };
  return deepFreeze(action);
}

function deepFreeze<T>(value: T): T {
  if (value !== null && typeof value === "object" && !Object.isFrozen(value)) {
    for (const nested of Object.values(value as Record<string, unknown>)) deepFreeze(nested);
    Object.freeze(value);
  }
  return value;
}
