function assertPortableSignatureRequestV1(
  raw: unknown,
  launch: Readonly<CanonicalCustomGraphLaunchV1>,
): any {
  const request = exactRecord(raw, [
    "adminWalletRequest", "approval", "compileInputHash", "compileRequest", "finalizedAnchor",
    "launchWallet", "permit", "permitDigest", "planHash", "preflight", "reissueOf",
    "requestHash", "safeMessageDigest", "schemaVersion",
  ], "portable signature request");
  if (request.schemaVersion !== "programmable.manual-github-router-signature-request.v1") {
    throw new TypeError("portable signature request schema is invalid");
  }
  const approval = assertVerifiedGitHubRouterApprovalV1(
    request.approval as VerifiedGitHubRouterApprovalV1,
  );
  const compileRequest = assertCustomGraphCompileRequestV1(
    request.compileRequest as RouterCustomGraphCompileRequestV1,
  );
  const preflight = assertRouterPreflightEvidenceV1(request.preflight, launch);
  const permitRecord = record(request.permit, "portable permit") as unknown as LaunchPermitV1;
  const permit = createLaunchPermitV1({
    launch,
    launchWallet: approval.claim.approvedLaunchWallet,
    validAfter: permitRecord.validAfter,
    deadline: permitRecord.deadline,
    nonce: permitRecord.nonce,
  });
  const adminRequest = assertAdminMetaMaskSafeMessageRequestV1(request.adminWalletRequest as any);
  const permitDigest = computePermitDigestV1(permit);
  const safeMessageDigest = computeSafeMessageSigningDigestV1(permitDigest);
  const reissueOf = request.reissueOf === null
    ? null
    : sha256(request.reissueOf, "portable reissue request hash");
  const previousPermitDeadline = preflight.unconsumed.previousPermit.previousPermitDeadline;
  if (
    canonicalizeJson(request.permit) !== canonicalizeJson(permit)
    || request.planHash !== launch.planHash
    || request.planHash !== approval.claim.planHash
    || request.compileInputHash !== approval.claim.compileInputHash
    || request.compileInputHash !== compileRequest.compileInputHash
    || request.launchWallet !== approval.claim.approvedLaunchWallet
    || request.launchWallet !== compileRequest.launchWallet
    || approval.claim.repositoryId !== compileRequest.repositoryId
    || approval.claim.pullRequestNumber !== compileRequest.pullRequestNumber
    || approval.claim.headRepositoryId !== compileRequest.headRepositoryId
    || approval.claim.headSha !== compileRequest.headSha
    || approval.claim.treeSha !== compileRequest.treeSha
    || approval.claim.approvedGitHubUserId !== compileRequest.approvedGitHubUserId
    || computeRouterApprovalRevisionHashV1(approval.claim.approvalRevision)
      !== compileRequest.approvalRevisionHash
    || request.permitDigest !== permitDigest
    || request.safeMessageDigest !== safeMessageDigest
    || adminRequest.permitDigest !== permitDigest
    || adminRequest.safeMessageDigest !== safeMessageDigest
    || adminRequest.issuedAtChainTimestamp !== preflight.chainClock.maximumTimestamp
    || adminRequest.expiresAtChainTimestamp !== permit.deadline
    || canonicalizeJson(request.finalizedAnchor) !== canonicalizeJson(preflight.finalizedAnchor)
    || preflight.targetCount !== launch.plan.route.expectedOutputs.length
    || (reissueOf === null) !== (previousPermitDeadline === null)
    || (reissueOf !== null && previousPermitDeadline !== null && (
      BigInt(permit.validAfter) <= BigInt(previousPermitDeadline)
      || BigInt(preflight.finalizedAnchor.timestamp) <= BigInt(previousPermitDeadline)
    ))
  ) throw new TypeError("portable signature request transitive binding is invalid");
  assertHashRecord(request, request.schemaVersion, "requestHash");
  return request;
}

function assertPortablePreparedV1(
  raw: unknown,
  request: any,
  launch: Readonly<CanonicalCustomGraphLaunchV1>,
): any {
  const prepared = exactRecord(raw, [
    "adminSignature", "approval", "browserAction", "calldata", "compileInputHash",
    "compileRequest", "componentSetHash", "expectedComponents", "expectedLaunchId",
    "expectedPoolId", "expectedStampHash", "finalizedAnchor", "idempotencyKey",
    "launchWallet", "permit", "permitDigest", "planHash", "poolKeyHash", "preflight",
    "preparationHash", "safeMessageDigest", "safeTypedData", "schemaVersion",
    "signatureRequestHash",
  ], "portable prepared launch");
  if (prepared.schemaVersion !== "programmable.prepared-github-router-launch.v3") {
    throw new TypeError("portable prepared launch schema is invalid");
  }
  const approval = assertVerifiedGitHubRouterApprovalV1(prepared.approval as any);
  const preflight = assertRouterPreflightEvidenceV1(prepared.preflight, launch);
  const adminSignature = acceptManualSafeOwnerSignatureV1({
    request: request.adminWalletRequest,
    rawSignature65: record(prepared.adminSignature, "portable admin signature")
      .rawSignature65 as EvmHexV1,
  });
  const calldata = encodeLaunchAndStampCalldataV1({
    permit: request.permit,
    stampRequest: launch.plan.stampRequest,
    routePayload: launch.routePayload,
    signature: adminSignature.rawSignature65,
  });
  const browserAction = createBrowserWalletRouterActionV1({
    permit: request.permit,
    calldata,
    pendingNonce: preflight.pendingNonce,
  });
  const expectedComponents = launch.plan.stampRequest.components.map((component) => ({
    account: component.account,
    runtimeCodeHash: component.runtimeCodeHash,
    kind: component.kind,
  }));
  const expectedStampHash = computeLaunchStampHashV1({
    permit: request.permit,
    stampRequest: launch.plan.stampRequest,
    permitDigest: request.permitDigest,
  });
  const idempotencyKey = canonicalSha256("programmable.manual-router-launch-identity.v1", {
    approvalBindingHash: approval.approvalBindingHash,
    planHash: launch.planHash,
    compileInputHash: request.compileInputHash,
    launchWallet: request.launchWallet,
    routeNonce: request.compileRequest.routeNonce,
  });
  if (
    prepared.signatureRequestHash !== request.requestHash
    || approval.approvalBindingHash !== request.approval.approvalBindingHash
    || canonicalizeJson(prepared.compileRequest) !== canonicalizeJson(request.compileRequest)
    || prepared.planHash !== launch.planHash
    || prepared.compileInputHash !== request.compileInputHash
    || prepared.launchWallet !== request.launchWallet
    || canonicalizeJson(prepared.permit) !== canonicalizeJson(request.permit)
    || prepared.permitDigest !== request.permitDigest
    || prepared.safeMessageDigest !== request.safeMessageDigest
    || canonicalizeJson(prepared.safeTypedData)
      !== canonicalizeJson(safeMessageTypedDataV1(request.permitDigest))
    || canonicalizeJson(prepared.adminSignature) !== canonicalizeJson(adminSignature)
    || prepared.calldata !== calldata
    || canonicalizeJson(prepared.browserAction) !== canonicalizeJson(browserAction)
    || prepared.expectedStampHash !== expectedStampHash
    || prepared.expectedLaunchId !== launch.plan.stampRequest.launchId
    || prepared.expectedPoolId !== launch.poolId
    || prepared.poolKeyHash !== launch.poolKeyHash
    || prepared.componentSetHash !== launch.componentSetHash
    || canonicalizeJson(prepared.expectedComponents) !== canonicalizeJson(expectedComponents)
    || canonicalizeJson(prepared.finalizedAnchor) !== canonicalizeJson(preflight.finalizedAnchor)
    || prepared.idempotencyKey !== idempotencyKey
  ) throw new TypeError("portable prepared launch action or hash chain drifted");
  assertHashRecord(prepared, prepared.schemaVersion, "preparationHash");
  return prepared;
}

