function assertExpectedCurrentHeadV1(
  request: Readonly<ManualRouterSignedArtifactPublishRequestV1>,
  currentPointer: Readonly<ManualRouterApplicantPointerV1> | undefined,
  currentEntry: ManualRouterApplicantIndexV1["entries"][number] | undefined,
): void {
  const reissueOf = request.signedArtifact.preparationArtifact.signatureRequest.reissueOf;
  if (reissueOf === null) {
    if (
      request.expectedPreviousPointerHash !== null
      || currentPointer !== undefined
      || currentEntry !== undefined
    ) throw new TypeError("portable initial publish does not start from an empty subject head");
    return;
  }
  const previous = request.signedArtifact.preparationArtifact.signatureRequest.preflight
    .unconsumed.previousPermit;
  const transaction = previous.transaction;
  const dispositionMatches = currentPointer?.state === "signed-permit-available"
    ? currentPointer.submittedTransactionHash === null && transaction === null
    : currentPointer?.state === "submitted-awaiting-finality"
      ? currentPointer.submittedTransactionHash !== null
        && transaction?.transactionHash === currentPointer.submittedTransactionHash
        && transaction.disposition === "absent-after-finalized-deadline"
      : currentPointer?.state === "submission-failed-awaiting-expiry"
        && currentPointer.submittedTransactionHash !== null
        && currentPointer.failedTransactionEvidenceHash !== null
        && transaction?.transactionHash === currentPointer.submittedTransactionHash
        && transaction.disposition === "finalized-reverted";
  if (
    currentPointer === undefined
    || currentEntry === undefined
    || currentEntry.pointerHash !== currentPointer.pointerHash
    || request.expectedPreviousPointerHash !== currentPointer.pointerHash
    || currentPointer.signatureRequestHash !== reissueOf
    || currentPointer.deadline === null
    || previous.previousPermitDeadline !== currentPointer.deadline
    || !dispositionMatches
  ) throw new TypeError("portable signed reissue does not extend the exact current subject head");
}

function assertCurrentApprovalV1(
  current: Readonly<VerifiedGitHubRouterApprovalV1>,
  stored: Readonly<VerifiedGitHubRouterApprovalV1>,
  metadata: Record<string, unknown>,
  source: Readonly<GitHubApplicantSourceRevisionV1>,
): void {
  const applicant = record(metadata.applicant, "portable Applicant identity");
  if (
    current.approvalBindingHash !== stored.approvalBindingHash
    || canonicalizeJson(current.claim) !== canonicalizeJson(stored.claim)
    || current.pullRequestAuthorGitHubUserId !== stored.pullRequestAuthorGitHubUserId
    || current.pullRequestAuthorGitHubLogin.toLowerCase()
      !== String(applicant.githubLogin).toLowerCase()
    || current.sourceRepositoryId !== source.repositoryId
    || current.sourceRepositoryUrl !== source.repositoryUrl
    || current.sourceCommitSha !== source.commitSha
    || current.sourceTreeSha !== source.treeSha
  ) throw new TypeError("portable Applicant GitHub currentness drifted");
}

function previousPermitInputV1(request: any): Readonly<{
  deadline: string;
  transactionHash: EvmBytes32V1 | null;
  expectedDisposition: "not-submitted" | "absent-after-finalized-deadline" | "finalized-reverted";
}> | null {
  if (request.reissueOf === null) return null;
  const previous = request.preflight.unconsumed.previousPermit;
  return {
    deadline: previous.previousPermitDeadline,
    transactionHash: previous.transaction?.transactionHash ?? null,
    expectedDisposition: previous.transaction?.disposition ?? "not-submitted",
  };
}

function assertLivePermitWindowV1(
  permit: Readonly<LaunchPermitV1>,
  preflight: Readonly<RouterPreflightEvidenceV1>,
): void {
  const minimum = BigInt(preflight.chainClock.minimumTimestamp);
  const maximum = BigInt(preflight.chainClock.maximumTimestamp);
  if (
    minimum < BigInt(permit.validAfter)
    || maximum > BigInt(permit.deadline)
    || BigInt(permit.deadline) - maximum
      < BigInt(MANUAL_ROUTER_MINIMUM_REMAINING_SECONDS_V1)
  ) throw new TypeError("portable signed permit is not live with the 120-second chain buffer");
}

async function assertManualOwnerRecoveryV1(
  rpc: RouterFinalityReadAuthorityV1,
  digest: EvmBytes32V1,
  signature: EvmHexV1,
): Promise<void> {
  const raw = signature.slice(2);
  if (raw.length !== 130) throw new TypeError("portable raw signature is not 65 bytes");
  const r = raw.slice(0, 64);
  const s = raw.slice(64, 128);
  const v = BigInt(`0x${raw.slice(128)}`);
  const data = `0x${digest.slice(2)}${v.toString(16).padStart(64, "0")}${r}${s}` as EvmHexV1;
  const recovered = await rpc.ethCallConsensus({ to: ECRECOVER_PRECOMPILE, data }, "latest");
  const expected = `0x${"00".repeat(12)}${BINDING.permitAuthoritySafe.manualOwner.slice(2)}`;
  if (recovered !== expected) throw new TypeError("portable signature does not recover the Safe owner");
}

function assertPortableApplicantHeadV1(input: Readonly<{
  index: ManualRouterApplicantIndexV1 | null;
  pointers: readonly ManualRouterApplicantPointerV1[];
  claim: Readonly<GitHubRouterApprovalClaimV1>;
}>): Readonly<{
  index: Readonly<ManualRouterApplicantIndexV1> | null;
  pointers: readonly Readonly<ManualRouterApplicantPointerV1>[];
}> {
  if (!Array.isArray(input.pointers)) throw new TypeError("portable Applicant pointers are invalid");
  const pointers = input.pointers.map(assertPortableApplicantPointerV1);
  if (input.index === null) {
    if (pointers.length !== 0) {
      throw new TypeError("portable initial Applicant head must be absent");
    }
    return deepFreeze({ index: null, pointers });
  }
  const index = assertPortableApplicantIndexV1(input.index, pointers);
  if (
    index.approvedGitHubUserId !== input.claim.approvedGitHubUserId
    || index.approvedLaunchWallet !== input.claim.approvedLaunchWallet
  ) throw new TypeError("portable Applicant head principal is invalid");
  return deepFreeze({ index, pointers });
}

function assertPortableApplicantPointerV1(raw: unknown): Readonly<ManualRouterApplicantPointerV1> {
  const pointer = exactRecord(raw, [
    "approvalBindingHash", "deadline", "failedTransactionEvidenceHash", "finalizedProofHash",
    "headSha", "pointerHash", "preparationArtifactHash", "previousPointerHash", "routeNonce",
    "schemaVersion", "signatureRequestHash", "signedArtifactHash", "signedDescriptorHash", "state",
    "subject", "submittedTransactionHash", "treeSha", "updatedAtEpochSeconds", "validAfter",
  ], "portable Applicant pointer");
  if (pointer.schemaVersion !== "programmable.manual-router-applicant-pointer.v1") {
    throw new TypeError("portable Applicant pointer schema is invalid");
  }
  assertHashRecord(pointer, pointer.schemaVersion, "pointerHash");
  return deepFreeze(structuredClone(pointer) as unknown as ManualRouterApplicantPointerV1);
}

function assertPortableApplicantIndexV1(
  raw: unknown,
  pointers: readonly Readonly<ManualRouterApplicantPointerV1>[],
): Readonly<ManualRouterApplicantIndexV1> {
  const index = exactRecord(raw, [
    "approvedGitHubUserId", "approvedLaunchWallet", "entries", "indexHash",
    "previousIndexHash", "schemaVersion",
  ], "portable Applicant index");
  if (
    index.schemaVersion !== "programmable.manual-router-applicant-index.v1"
    || !Array.isArray(index.entries)
  ) throw new TypeError("portable Applicant index schema is invalid");
  assertHashRecord(index, index.schemaVersion, "indexHash");
  const pointerBySubject = new Map(pointers.map((pointer) =>
    [pointer.subject.subjectHash, pointer] as const));
  if (
    index.entries.length !== pointers.length
    || index.entries.some((entryValue) => {
      const entry = record(entryValue, "portable Applicant index entry");
      return pointerBySubject.get(sha256(entry.subjectHash, "portable index subject hash"))
        ?.pointerHash !== entry.pointerHash;
    })
  ) throw new TypeError("portable Applicant index is not bound to current pointers");
  return deepFreeze(structuredClone(index) as unknown as ManualRouterApplicantIndexV1);
}

function createPortableSignedPointerV1(input: Readonly<{
  artifact: Readonly<ManualRouterCompleteSignedArtifactV1>;
  previousPointerHash: Sha256Digest | null;
  updatedAtEpochSeconds: string;
}>): Readonly<ManualRouterApplicantPointerV1> {
  const artifact = input.artifact;
  const core = {
    schemaVersion: "programmable.manual-router-applicant-pointer.v1" as const,
    subject: artifact.preparationArtifact.subject,
    state: "signed-permit-available" as const,
    approvalBindingHash: artifact.descriptor.approvalBindingHash,
    headSha: artifact.preparationArtifact.approvalClaim.headSha,
    treeSha: artifact.preparationArtifact.approvalClaim.treeSha,
    routeNonce: artifact.descriptor.routeNonce,
    preparationArtifactHash: artifact.preparationArtifact.preparationArtifactHash,
    signatureRequestHash: artifact.preparationArtifact.signatureRequest.requestHash,
    signedDescriptorHash: artifact.descriptor.descriptorHash,
    signedArtifactHash: artifact.signedArtifactHash,
    validAfter: artifact.descriptor.validAfter,
    deadline: artifact.descriptor.deadline,
    submittedTransactionHash: null,
    failedTransactionEvidenceHash: null,
    finalizedProofHash: null,
    previousPointerHash: input.previousPointerHash,
    updatedAtEpochSeconds: decimal(input.updatedAtEpochSeconds, "portable pointer update time"),
  };
  return deepFreeze({
    ...core,
    pointerHash: canonicalSha256(core.schemaVersion, core),
  });
}

function advancePortableApplicantIndexV1(input: Readonly<{
  previousIndex: Readonly<ManualRouterApplicantIndexV1> | null;
  previousPointers: readonly Readonly<ManualRouterApplicantPointerV1>[];
  nextPointer: Readonly<ManualRouterApplicantPointerV1>;
}>): Readonly<ManualRouterApplicantIndexV1> {
  const bySubject = new Map(input.previousPointers.map((pointer) =>
    [pointer.subject.subjectHash, pointer] as const));
  const current = bySubject.get(input.nextPointer.subject.subjectHash);
  if (
    (current === undefined && input.nextPointer.previousPointerHash !== null)
    || (current !== undefined && input.nextPointer.previousPointerHash !== current.pointerHash)
  ) throw new TypeError("portable Applicant pointer does not extend current head");
  bySubject.set(input.nextPointer.subject.subjectHash, input.nextPointer);
  const pointers = [...bySubject.values()].sort((left, right) =>
    left.subject.pullRequestNumber - right.subject.pullRequestNumber
    || compare(left.subject.subjectHash, right.subject.subjectHash));
  const entries = pointers.map((pointer) => ({
    subjectHash: pointer.subject.subjectHash,
    pointerHash: pointer.pointerHash,
    pullRequestNumber: pointer.subject.pullRequestNumber,
    approvalBindingHash: pointer.approvalBindingHash,
    headSha: pointer.headSha,
    treeSha: pointer.treeSha,
    routeNonce: pointer.routeNonce,
    state: pointer.state,
    signedArtifactHash: pointer.signedArtifactHash,
    validAfter: pointer.validAfter,
    deadline: pointer.deadline,
    submittedTransactionHash: pointer.submittedTransactionHash,
    failedTransactionEvidenceHash: pointer.failedTransactionEvidenceHash,
  }));
  const core = {
    schemaVersion: "programmable.manual-router-applicant-index.v1" as const,
    approvedGitHubUserId: input.nextPointer.subject.approvedGitHubUserId,
    approvedLaunchWallet: input.nextPointer.subject.approvedLaunchWallet,
    entries,
    previousIndexHash: input.previousIndex?.indexHash ?? null,
  };
  return deepFreeze({ ...core, indexHash: canonicalSha256(core.schemaVersion, core) });
}

function sourceRevision(raw: Record<string, unknown>): Readonly<GitHubApplicantSourceRevisionV1> {
  return Object.freeze({
    repositoryId: numericId(raw.repositoryId, "portable source repository id"),
    repositoryUrl: String(raw.repositoryUrl),
    commitSha: gitSha(raw.commitSha, "portable source commit"),
    treeSha: gitSha(raw.treeSha, "portable source tree"),
  });
}

function assertHashRecord(
  value: Record<string, unknown>,
  domain: string,
  hashField: string,
): void {
  const observed = sha256(value[hashField], `portable ${hashField}`);
  const core = Object.fromEntries(Object.entries(value).filter(([key]) => key !== hashField));
  if (observed !== canonicalSha256(domain, core)) {
    throw new TypeError(`portable ${hashField} is invalid`);
  }
}

function exactRecord(raw: unknown, keys: readonly string[], label: string): Record<string, any> {
  const value = record(raw, label);
  const actual = Reflect.ownKeys(value);
  const strings = actual.filter((key): key is string => typeof key === "string").sort(compare);
  const expected = [...keys].sort(compare);
  if (
    actual.length !== strings.length
    || strings.length !== expected.length
    || strings.some((key, index) => key !== expected[index])
  ) throw new TypeError(`${label} has unexpected fields`);
  return value;
}

function record(raw: unknown, label: string): Record<string, any> {
  if (raw === null || typeof raw !== "object" || Array.isArray(raw)) {
    throw new TypeError(`${label} is not an object`);
  }
  return raw as Record<string, any>;
}

function sha256(value: unknown, label: string): Sha256Digest {
  if (typeof value !== "string" || !/^sha256:[0-9a-f]{64}$/u.test(value)) {
    throw new TypeError(`${label} is invalid`);
  }
  return value as Sha256Digest;
}

function numericId(value: unknown, label: string): string {
  if (typeof value !== "string" || !/^[1-9][0-9]{0,19}$/u.test(value)) {
    throw new TypeError(`${label} is invalid`);
  }
  return value;
}

function gitSha(value: unknown, label: string): string {
  if (typeof value !== "string" || !/^[0-9a-f]{40}$/u.test(value)) {
    throw new TypeError(`${label} is invalid`);
  }
  return value;
}

function decimal(value: unknown, label: string): string {
  if (typeof value !== "string" || !/^(?:0|[1-9][0-9]*)$/u.test(value)) {
    throw new TypeError(`${label} is invalid`);
  }
  return value;
}

function applicantStatus(value: unknown): ManualRouterApplicantStatusV1 {
  if (![
    "permit-not-yet-valid",
    "ready",
    "reissue-required",
    "submitted-awaiting-finality",
    "failed-awaiting-expiry",
    "finalized",
  ].includes(value as string)) {
    throw new TypeError("portable current Applicant status is invalid");
  }
  return value as ManualRouterApplicantStatusV1;
}

function requiredEnvironmentValue(value: string | undefined, name: string): string {
  if (value === undefined || value.length === 0 || value.includes("\0")) {
    throw new TypeError(`${name} is required`);
  }
  return value;
}

function compare(left: string, right: string): number {
  return Buffer.compare(Buffer.from(left, "utf8"), Buffer.from(right, "utf8"));
}

function deepFreeze<T>(value: T): T {
  if (value !== null && typeof value === "object" && !Object.isFrozen(value)) {
    for (const nested of Object.values(value as Record<string, unknown>)) deepFreeze(nested);
    Object.freeze(value);
  }
  return value;
}
